/* Character, equipment and passive workspaces. Data stays with existing game owners. */
function uiSheetRows(rows){return `<dl class="sheet-rows">${rows.map(([n,v])=>`<div><dt>${uxEsc(n)}</dt><dd>${uxEsc(v)}</dd></div>`).join('')}</dl>`;}
function uiSheetGroup(name,rows,extra=''){return `<section class="sheet-group"><h3>${uxEsc(name)}</h3>${uiSheetRows(rows)}${extra}</section>`;}
function uiSheetIdentity(){
 const c=CHARS[G.char],url=typeof icon3dPortraitUrl==='function'?icon3dPortraitUrl(G.char):'';
 return `<div class="sheet-identity"><div><span class="sheet-caption">${uxEsc(c.title||'街頭冒險者')}</span><h3>${uxEsc(G.heroName||'未命名')}</h3><span>Lv. ${G.lvl} · ${uxEsc(c.n)}</span></div><button class="sheet-portrait" data-focus="character-switch" onclick="uiChooseCharacter()" aria-label="角色列表，目前職業${uxEsc(c.n)}"><span id="pvhost" class="sheet-portrait-preview" data-framing="portrait" aria-hidden="true">${url?`<img src="${url}" alt="" width="104" height="102">`:spr('role',48)}</span><small>角色列表</small></button><dl><div><dt>最深層數</dt><dd>${G.maxDepth}</dd></div><div><dt>天賦</dt><dd>${G.pass.length}／${talentBudget()}</dd></div><div><dt>代號</dt><dd>${uxEsc(uiCharacterCode())}</dd></div></dl></div>`;
}
function uiCharacterSheetHtml(){
 const s=G.st,c=CHARS[G.char],metric=(label,value,icon,unit='')=>`<div class="sheet-metric">${spr(icon,24)}<span>${label}</span><strong>${value}<small>${unit}</small></strong></div>`;
 return `<div class="character-view character-sheet" data-character="${G.char}">${charSegHtml()}<div class="sheet-surface">${uiSheetIdentity()}${careerAscensionSummary()}<section class="sheet-vitals" aria-label="戰鬥能力摘要">${metric('最大生命',tFmt(s.life),'heart')}${metric('DPS',tFmt(s.dps),'sword')}${metric('會心率',s.crit.toFixed(1),'star','%')}${metric('基礎回復',s.regen.toFixed(1),'heart','／秒')}</section><section class="sheet-defenses" aria-label="防禦摘要">${uiSheetRows([['護甲',tFmt(s.armor)],['護甲減傷',(s.red*100).toFixed(1)+'%'],['生命偷取',s.leech.toFixed(1)+'%']])}</section>${uiSheetGroup('生命與防禦',[['最大生命',tFmt(s.life)],['基礎生命回復',s.regen.toFixed(1)+'／秒'],['最大生命加成',s.lifePct.toFixed(1)+'%'],['護甲',tFmt(s.armor)],['護甲傷害減免',(s.red*100).toFixed(1)+'%']])}${uiSheetGroup('攻擊',[['普通攻擊傷害',tFmt(s.hit)],['每秒普通攻擊',s.aps.toFixed(2)+' 次'],['會心率',s.crit.toFixed(1)+'%'],['會心傷害',s.cm.toFixed(0)+'%'],['生命偷取',s.leech.toFixed(1)+'%'],['技能急速',s.haste.toFixed(1)+'%']])}${uiSheetGroup('元素傷害加成',[['火焰',s.fire.toFixed(1)+'%'],['冰霜',s.cold.toFixed(1)+'%'],['閃電',s.light.toFixed(1)+'%']])}<section class="sheet-group"><h3>目前技能</h3>${Object.entries(s.sk).map(([id,k])=>`<div class="sheet-skill">${sico(id,28)}<span>${SKILLS[id].n}<small>單次直傷 ${tFmt(k.hit)}</small></span><b>${k.cd.toFixed(2)} 秒</b></div>`).join('')||'<p>尚未裝上技能。到技能頁配置接線。</p>'}<button class="mb" onclick="openModal('skills')">管理技能</button><details class="sheet-note"><summary>預估值如何閱讀</summary><p>DPS不含召喚、持續傷害、條件連動與角色專技。基礎回復及偷取仍受戰鬥回復上限影響；實際傷害可到訓練場測量。</p></details></section>${professionVisualHtml()}</div>${directCharacterLinks()}${uiCharacterProfile()}</div>`;
}
function uiEquipmentRigHtml(){
 const c=CHARS[G.char],url=typeof icon3dPortraitUrl==='function'?icon3dPortraitUrl(G.char):'';
 return `<section class="equipment-rig" aria-label="目前配裝"><div class="rig-label"><span>目前配裝</span><button class="mb" onclick="openModal('dress')">外觀 ↗</button></div><div class="rig-layout">${Object.keys(SLOTN).map(slot=>`<div class="rig-slot rig-${slot}"><span>${SLOTN[slot]}</span>${uiEquippedTile(slot)}<small>${G.equip[slot]?RAR[G.equip[slot].r].n+' · Lv. '+G.equip[slot].il:'空欄位'}</small></div>`).join('')}<div class="rig-person">${url?`<img src="${url}" alt="${uxEsc(c.n)}" width="96" height="96">`:spr('role',48)}<span>${uxEsc(uiCharacterCode())}</span><small>Lv. ${G.lvl}</small></div></div><p class="sheet-caption">七個能力部位，純外觀另在裝扮調整。</p></section>`;
}
function uiWarehouseSheetHtml(){
 const cores=Object.values(G.armory),source=WAREHOUSE_UI.kind==='all'?[...G.inventory,...cores]:WAREHOUSE_UI.kind==='core'?cores:G.inventory,list=uiSortByDps(source.filter(it=>WAREHOUSE_UI.slot==='all'||it.slot===WAREHOUSE_UI.slot).slice().reverse(),WAREHOUSE_UI.sort),pages=Math.max(1,Math.ceil(list.length/WAREHOUSE_PAGE_SIZE));WAREHOUSE_UI.page=Math.max(0,Math.min(WAREHOUSE_UI.page,pages-1));
 const part=list.slice(0,WAREHOUSE_UI.limit||48),filter=(label,key,items)=>`<div class="bag-filter"><span>${label}</span><div class="ui-segments" role="group" aria-label="${label}">${items.map(([id,n])=>`<button data-focus="warehouse-${key==='slot'?'filter':key}-${id}" aria-pressed="${WAREHOUSE_UI[key]===id}" onclick="uiWarehouseFilter('${key}','${id}')">${n}</button>`).join('')}</div></div>`;
 return `<div class="inventory-sheet">${uiEquipmentRigHtml()}<div class="bag-currency" aria-label="資源"><span>金幣 <b>${tFmt(G.gold)}</b></span><span>零件 <b>${tFmt(G.parts)}</b></span><span>電路 <b>${tFmt(G.chips)}</b></span></div>${lootStorageToolsHtml()}<section class="bag-storage"><div class="ui-segments" role="group" aria-label="倉庫分類">${[['all','全部'],['gear','裝備 '+G.inventory.length],['core','傳奇 '+cores.length]].map(([id,n])=>`<button data-focus="warehouse-kind-${id}" aria-pressed="${WAREHOUSE_UI.kind===id}" onclick="uiWarehouseFilter('kind','${id}')">${n}</button>`).join('')}</div><div class="bag-tools">${filter('部位','slot',[['all','全部'],...Object.entries(SLOTN)])}${filter('排序','sort',[['new','最新'],['dps','DPS']])}</div><div class="bag-count">${directHelpButton('warehouse')}<span>${list.length} 件 · 已顯示 ${part.length} 件</span><span>裝備 <span id="ui-gear-count">${G.inventory.length}</span>／${whCap()}</span></div><div class="ui-item-grid ui-warehouse-list bag-grid" role="group" aria-label="${WAREHOUSE_UI.kind==='core'?'傳奇':'裝備'}網格">${part.map(it=>uiGearTile(it,!!it.lg)).join('')}${part.length?Array.from({length:(6-part.length%6)%6},()=>'<span class="bag-empty-cell" aria-hidden="true"></span>').join(''):'<p class="ui-grid-empty">目前沒有這類裝備。切換部位，或繼續冒險並走近掉落物拾取。</p>'}</div>${part.length<list.length?'<div class="warehouse-scroll-more" data-warehouse-more role="status">繼續捲動載入更多</div>':''}</section></div>`;
}
function uiGearCompareSheet(it){
 const current=G.equip[it.slot],a=calc({...G.equip,[it.slot]:it}),s=G.st,allowed=canUseGear(it),line=(n,x,y,unit='')=>{const d=y-x;return `<div><dt>${n}</dt><dd>${x.toFixed(1)} → ${y.toFixed(1)}${unit}<span class="compare-delta ${d>0?'up':d<0?'down':''}">${d>0?'+':''}${d.toFixed(1)}${unit}</span></dd></div>`;};
 const item=(v,label)=>`<section class="compare-item"><h3>${label}</h3>${v?`${v.lg?xico('legend',v.lg,48):eqico(v.slot,v.r,48,v)}<b>${uxEsc(v.name)}</b><p>${RAR[v.r].n} · 物品等級 ${v.il}</p><ul>${itemLines(v).filter((l,i)=>i===0||i>v.aff.length).map(l=>`<li>${uxEsc(l.t)}</li>`).join('')}</ul>${gearRollProfile(v)}`:'<p>目前部位空置。</p>'}</section>`;
 return `<div class="equipment-compare">${item(it,'選中裝備')}${item(current,'目前穿著')}</div>${allowed?`<h3>換上後的能力</h3><dl class="sheet-rows compare-values">${line('DPS',s.dps,a.dps)}${line('最大生命',s.life,a.life)}${line('會心率',s.crit,a.crit,'%')}${line('護甲減傷',s.red*100,a.red*100,'%')}</dl>`:'<p>角色不符，只可收藏；不顯示無法穿著的配裝預估。</p>'}`;
}

/* UI-only exploration state; never serialized or used as a parallel talent model. */
const TALENT_VIEW={selected:null,zoom:null,fit:true,left:null,top:null,query:'',gesture:null};
const TALENT_BRANCH={A:'耐久',B:'元素',C:'會心',D:'超頻',E:'回授',F:'電池',R:'接線',S:'起點'};
const talentPosition=n=>({x:1120+n.x*8,y:1120+n.y*8});
function uiTreeSelect(id){if(!TREE[id])return;uiTreeRemember();TALENT_VIEW.selected=id;const el=$('talent-detail');if(el){el.hidden=false;el.innerHTML=uiTreeDetailHtml();}document.querySelectorAll('[data-talent]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.talent===id));b.tabIndex=b.dataset.talent===id?0:-1});}
function uiStoreTalentBuild(){const ok=saveBuild();uxAnnounce(ok?'已儲存目前構築。':'目前不能儲存，請先結束挑戰或整理倉庫。');}
function uiTreeNodeKey(e,id){
 const dirs={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]},d=dirs[e.key];if(!d&&e.key!=='Home')return;e.preventDefault();
 const n=TREE[id],next=e.key==='Home'?'S':Object.entries(TREE).filter(([k,m])=>k!==id&&(m.x-n.x)*d[0]+(m.y-n.y)*d[1]>1).sort((a,b)=>{const score=m=>Math.hypot(m.x-n.x,m.y-n.y)+3*Math.abs((m.x-n.x)*d[1]-(m.y-n.y)*d[0]);return score(a[1])-score(b[1])})[0]?.[0];
 if(next){uiTreeSelect(next);document.querySelector('[data-talent="'+next+'"]')?.focus();}
}
function uiTreeDetailHtml(){
 if(!TALENT_VIEW.selected)return '';
 const id=TALENT_VIEW.selected,n=TREE[id]||TREE.S,got=G.pass.includes(id),open=canAllocateTalent(id),refund=got&&!G.run&&!G.train&&connectedTalents(G.pass.filter(k=>k!==id)),firm=!passiveLegacy()&&FIRMWARE[id],name=firm?firm.n:n.big?n.name:TALENT_BRANCH[id[0]]+'節點',reason=id==='S'?'所有路徑由這裡連出':got?'已分配':G.run?.city||G.train?'挑戰或訓練進行中':passiveLegacy()?'需先轉換舊制配置':!nodeOpen(id)?'尚未連接起點':passPoints()<=0?'可用點數不足':firm&&firmwareCount(G.pass)>=FIRMWARE_LIMIT?'韌體已達上限':'可分配';
 const next=open?calc(G.equip,[...G.pass,id],G.slots,G.supp):null;
 return `<div class="talent-detail-head"><span>${TALENT_BRANCH[id[0]]||'路徑'} · ${firm?'韌體':'節點'}</span><strong>${uxEsc(name)}</strong><span>${reason}</span></div><p>${uxEsc(id==='S'?'選擇支線，連接節點建立你的構築。':firm?firm.d:effText(n.eff))}</p>${next?uiSheetRows([['DPS',tFmt(G.st.dps)+' → '+tFmt(next.dps)],['最大生命',tFmt(G.st.life)+' → '+tFmt(next.life)]]):''}<div class="uxactions"><button class="mb pri" data-focus="talent-allocate" ${open?'':'disabled'} onclick="uiAllocateTalent('${id}')">分配 1 點</button><button class="mb" data-focus="talent-refund" ${refund?'':'disabled'} onclick="uiRefundTalent('${id}')">退回 1 點</button></div>${got&&!refund?'<p class="sheet-caption">只可退回不會切斷路徑的末端節點；挑戰期間不能調整。</p>':''}`;
}
function uiTalentMapHtml(){
 if(TALENT_VIEW.fit||TALENT_VIEW.zoom==null)TALENT_VIEW.zoom=uiTreeFitScale();
 const z=TALENT_VIEW.zoom,lit=id=>id==='S'||G.pass.includes(id),lines=[],nodes=[];
 for(const [id,n]of Object.entries(TREE)){
  const p=talentPosition(n),got=lit(id),open=canAllocateTalent(id),label=id==='S'?'起點':FIRMWARE[id]?.n||talentName(id);
  for(const link of n.links)if(id<link){const q=talentPosition(TREE[link]);lines.push(`<line class="${got&&lit(link)?'connected':''}" x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"/>`);}
  nodes.push(`<button class="tn talent-node ${got?'got':open?'open':'locked'} ${n.big?'major':''}" style="left:${p.x*z}px;top:${p.y*z}px;--node-color:${n.col};--overview-size:${Math.max(7,Math.min(24,(n.big?38:24)*z))}px" data-tree="${id}" data-talent="${id}" tabindex="${(TALENT_VIEW.selected||'S')===id?0:-1}" onkeydown="uiTreeNodeKey(event,'${id}')" aria-pressed="${TALENT_VIEW.selected===id}" aria-label="${uxEsc(label)}，${got?'已分配':open?'可分配':'未解鎖，按下查看'}" onclick="uiTreeActivate('${id}')"><i aria-hidden="true">${id==='S'?'◎':n.big?'◆':got?'●':'·'}</i><span>${uxEsc(id==='S'?'起點':FIRMWARE[id]?.n||(n.big?n.name.split(/[：:]/)[0]:talentName(id)))}${FIRMWARE_SHORT[id]&&!passiveLegacy()&&z>=.5?`<small class="fw-short">${uxEsc(FIRMWARE_SHORT[id])}</small>`:''}</span></button>`);
 }
 return `<div id="talent-viewport" class="talent-viewport${z<.75?' overview':''}" role="region" tabindex="0" aria-label="可捲動天賦盤，方向鍵捲動，或使用平移按鈕" onwheel="talentWheel(event)" onscroll="uiTreeRemember()" onpointerdown="uiTreePanStart(event)" onpointermove="uiTreePanMove(event)" onpointerup="uiTreePanEnd(event)" onpointercancel="uiTreePanEnd(event)"><div class="talent-plane" style="width:${2240*z}px;height:${2240*z}px"><svg viewBox="0 0 2240 2240" aria-hidden="true">${lines.join('')}</svg>${nodes.join('')}</div></div>`;
}
function uiTalentWorkspaceHtml(){
 return `<div class="talent-workspace">${charSegHtml()}<div class="talent-builds" role="group" aria-label="天賦構築"><div class="tb-slots"><span>構築</span>${[0,1,2].map(i=>`<button class="mb" aria-pressed="${(G.bi||0)===i}" onclick="switchBuild(${i})">${i+1}</button>`).join('')}<button class="mb" onclick="uiStoreTalentBuild()">儲存</button></div><div class="tb-right"><span class="talent-points"><b>${passPoints()}</b> 點可用</span>${directHelpButton('tree')}</div></div>${passiveLegacy()?'<p class="sheet-caption">目前保留舊配置，轉換後才可重新分配。</p><button class="mb" onclick="uiTalentPreview()">預覽免費轉換</button>':''}<div class="talent-tools"><div role="group" aria-label="天賦盤縮放"><button class="mb" data-talent-zoom="out" aria-label="縮小天賦盤" onclick="uiTreeZoom(-.25)" ${TALENT_VIEW.zoom<=.1?'disabled':''}>−</button><span id="talent-zoom-readout">${Math.round(TALENT_VIEW.zoom*100)}%</span><button class="mb" data-talent-zoom="in" aria-label="放大天賦盤" onclick="uiTreeZoom(.25)" ${TALENT_VIEW.zoom>=1.75?'disabled':''}>＋</button></div><div class="tt-nav"><button class="mb" onclick="uiTreeOverview()">全貌</button><button class="mb" onclick="uiTreeCenter()">起點</button></div><div class="talent-search"><label class="uxsr" for="talent-search">搜尋天賦</label><input id="talent-search" type="search" value="${uxEsc(TALENT_VIEW.query)}" placeholder="搜尋天賦" oninput="if(!event.isComposing)uiTreeSearch(this.value)" oncompositionend="uiTreeSearch(this.value)"><button class="mb" id="talent-clear" aria-label="清除天賦搜尋" ${TALENT_VIEW.query?'':'hidden'} onclick="uiTreeSearch('');document.getElementById('talent-search').value='';document.getElementById('talent-search').focus()">×</button></div></div>${uiTalentMapHtml()}<section id="talent-detail" tabindex="-1" class="talent-detail" aria-label="節點詳情" aria-live="polite" ${TALENT_VIEW.selected?'':'hidden'}>${uiTreeDetailHtml()}</section><p id="talent-results" class="sheet-caption" role="status"></p><details class="talent-list"><summary>節點清單</summary><div id="talent-list">${uiTalentListHtml()}</div></details><details class="sheet-extra"><summary>盤面操作</summary><p class="sheet-caption">點可分配節點即加 1 點，已分配節點只看詳情。拖曳空白處、捲動或使用按鈕探索；焦點在節點時可用方向鍵移動。</p><div class="talent-pan" role="group" aria-label="平移天賦盤"><button class="mb" aria-label="天賦盤向左" onclick="uiTreePan(-160,0)">←</button><button class="mb" aria-label="天賦盤向上" onclick="uiTreePan(0,-160)">↑</button><button class="mb" aria-label="天賦盤向下" onclick="uiTreePan(0,160)">↓</button><button class="mb" aria-label="天賦盤向右" onclick="uiTreePan(160,0)">→</button></div><button class="mb" ${G.run?.city||G.train?'disabled':''} onclick="uiRespec()">重置天賦 · ${tFmt(100*G.lvl)} 金幣</button></details></div>`;
}
function uiTalentListHtml(){const q=TALENT_VIEW.query.trim().toLocaleLowerCase();return Object.entries(TREE).filter(([id])=>id!=='S'&&(!q||(TALENT_BRANCH[id[0]]+' '+talentName(id)).toLocaleLowerCase().includes(q))).map(([id])=>`<button class="mb" onclick="uiTreeActivate('${id}');document.getElementById('talent-detail').scrollIntoView({block:'nearest'})"><span>${TALENT_BRANCH[id[0]]} · ${G.pass.includes(id)?'已分配':canAllocateTalent(id)?'可分配':'未連接'}</span>${uxEsc(talentName(id))}</button>`).join('')||'<p>沒有符合的節點，請換字詞或清除搜尋。</p>';}
function uiTreeFitScale(){return Math.max(.1,Math.min(.65,(($('mbody')?.clientWidth||innerWidth)-44)/2240,Math.min(500,innerHeight*.55)/2240));}
function uiTreeOverview(){TALENT_VIEW.fit=true;TALENT_VIEW.zoom=null;TALENT_VIEW.left=null;TALENT_VIEW.top=null;renderModal();}
function uiTreeRemember(){const v=$('talent-viewport');if(v?.dataset.ready==='true'){TALENT_VIEW.left=v.scrollLeft;TALENT_VIEW.top=v.scrollTop;}}
function uiTreeMount(){const v=$('talent-viewport');if(!v)return;v.scrollLeft=TALENT_VIEW.left??1120*TALENT_VIEW.zoom-v.clientWidth/2;v.scrollTop=TALENT_VIEW.top??1120*TALENT_VIEW.zoom-v.clientHeight/2;v.dataset.ready='true';uiTreeSearch(TALENT_VIEW.query);}
function uiTreeSearch(value){TALENT_VIEW.query=value;const q=value.trim().toLocaleLowerCase(),list=$('talent-list');if(list)list.innerHTML=uiTalentListHtml();let matches=0;document.querySelectorAll('[data-talent]').forEach(b=>{const id=b.dataset.talent,match=!q||(TALENT_BRANCH[id[0]]+' '+talentName(id)).toLocaleLowerCase().includes(q);b.classList.toggle('search-match',!!q&&match);if(match&&id!=='S')matches++;});const result=$('talent-results');if(result)result.textContent=q?(matches?'符合 '+matches+' 個節點。可展開清單查看。':'沒有符合的節點，請換字詞或清除搜尋。'):'';const clear=$('talent-clear');if(clear)clear.hidden=!value;}
function uiTreeCenter(){const v=$('talent-viewport');if(!v)return;TALENT_VIEW.left=1120*TALENT_VIEW.zoom-v.clientWidth/2;TALENT_VIEW.top=1120*TALENT_VIEW.zoom-v.clientHeight/2;uiTreeMount();}
function uiTreePan(x,y){const v=$('talent-viewport');if(v){v.scrollLeft+=x;v.scrollTop+=y;uiTreeRemember();}}
function uiTreeZoom(delta){uiTreeRemember();const old=TALENT_VIEW.zoom,z=Math.max(.1,Math.min(1.75,old+delta)),v=$('talent-viewport');if(z===old||!v)return;TALENT_VIEW.left=(v.scrollLeft+v.clientWidth/2)*z/old-v.clientWidth/2;TALENT_VIEW.top=(v.scrollTop+v.clientHeight/2)*z/old-v.clientHeight/2;TALENT_VIEW.fit=false;TALENT_VIEW.zoom=z;renderModal();}
