function deviceCircuitModel(kind,id){
 const g=new T3.Group(),col=kind==='skill'?(SKILLS[id]?.col||'#88c8df'):(GEM_COL[id]||'#8ba5ce'),dark=m3('#334358'),silver=m3('#bdcadb'),accent=m3(col);let hash=0;for(const c of id)hash=(hash*31+c.charCodeAt(0))>>>0;
 mk(new T3.BoxGeometry(3.1,.55,2.7),dark,0,0,0,g);mk(new T3.BoxGeometry(2.65,.3,2.3),silver,0,.4,0,g);for(const side of[-1,1])for(const x of[-.9,0,.9])mk(new T3.BoxGeometry(.25,.22,.55),silver,x,0,side*1.5,g);
 const order=Object.keys(kind==='skill'?SKILLS:SUPPS),variant=order.indexOf(id);
 // Each function owns a distinct silhouette; six binary trace pins provide a redundant identifier.
 if(kind==='skill'){
  if(id==='RIFT'){for(const x of[-.6,0,.6])mk(new T3.OctahedronGeometry(.5,0),accent,x,1.2+Math.abs(x),0,g).scale.set(.6,1.8,.5);}
  else if(id==='RESONANCE'){for(const y of[.7,1.2,1.7])mk(new T3.TorusGeometry(.65,.08,4,12),accent,0,y,0,g).rotation.x=Math.PI/2;mk(new T3.CylinderGeometry(.2,.2,1.4,6),silver,0,1.1,0,g);}
  else if(id==='GRAVITY'){mk(new T3.SphereGeometry(.45,8,5),dark,0,1,0,g);for(const a of[0,Math.PI/2])mk(new T3.TorusGeometry(.9,.08,4,12),accent,0,1,0,g).rotation.y=a;}
  else
  if(['SWARM','GUARDIAN'].includes(id)){mk(new T3.BoxGeometry(id==='GUARDIAN'?1.4:.7,1,.8),silver,0,1,0,g);for(const x of[-.9,.9])mk(new T3.BoxGeometry(.4,id==='GUARDIAN'?1:.2,1),accent,x,1,0,g);}
  else if(id==='ARROWS'){for(const x of[-.7,0,.7]){mk(new T3.CylinderGeometry(.08,.08,1.3,4),silver,x,1.1,0,g);mk(new T3.ConeGeometry(.25,.5,4),accent,x,.3,0,g).rotation.z=Math.PI;}}
  else if(id==='GIANTBLADE'){mk(new T3.BoxGeometry(.45,1.7,.2),accent,0,1.5,0,g);mk(new T3.BoxGeometry(1.1,.15,.35),silver,0,.8,0,g);}
  else if(id==='OVERTURE'){for(const x of[-.5,.5]){mk(new T3.OctahedronGeometry(.35,0),accent,x,.8,0,g);mk(new T3.BoxGeometry(.15,1.2,.15),silver,x+.2,1.3,0,g);}mk(new T3.BoxGeometry(1,.2,.2),silver,0,1.9,0,g);}
  else if(['FIRE','METEOR'].includes(id)){mk(new T3.CylinderGeometry(.5,.5,1.4,6),accent,0,1.15,0,g);if(id==='METEOR')for(const x of[-.9,.9])mk(new T3.BoxGeometry(.7,.15,1.2),silver,x,1.2,0,g);}
  else if(['FROST','PULSE','MAGNET'].includes(id)){const ring=mk(new T3.TorusGeometry(.75,.15,4,id==='FROST'?6:10),accent,0,1,0,g);if(id==='PULSE')for(const x of[-.9,.9])mk(new T3.BoxGeometry(.15,1.3,.5),accent,x,1,0,g);if(id==='MAGNET')mk(new T3.BoxGeometry(.6,.7,.4),dark,0,.4,0,g);}
  else if(id==='CHAIN'){for(const x of[-.7,0,.7])mk(new T3.OctahedronGeometry(.34,0),accent,x,1,0,g);}
  else if(id==='SPAM'){for(let i=0;i<3;i++){const card=mk(new T3.BoxGeometry(1.2,.08,.8),silver,i*.25-.25,.8+i*.3,0,g);card.rotation.y=i*.3;}}
  else if(id==='FLICKER'){mk(new T3.BoxGeometry(1.6,1,.7),silver,0,1,0,g);mk(new T3.CylinderGeometry(.4,.4,.4,8),accent,0,1,.5,g).rotation.x=Math.PI/2;}
  else if(id==='BEAM'||id==='RAIL'){mk(new T3.BoxGeometry(id==='RAIL'?1.9:.4,.4,id==='RAIL'?.5:1.9),accent,0,1,0,g);if(id==='RAIL')for(const z of[-.4,.4])mk(new T3.BoxGeometry(1.8,.25,.15),silver,0,1,z,g);}
  else if(id==='DISC'||id==='ORBIT'){mk(new T3.CylinderGeometry(.85,.85,.15,12),accent,0,1,0,g);mk(new T3.CylinderGeometry(.3,.3,.19,8),dark,0,1,0,g);if(id==='ORBIT')mk(new T3.TorusGeometry(1.1,.08,3,12),silver,0,1,0,g).rotation.x=.5;}
  else if(id==='COIL'){for(const y of[.7,1,1.3])mk(new T3.TorusGeometry(.6,.09,4,10),accent,0,y,0,g).rotation.x=Math.PI/2;}
  else if(id==='DEFRAG'){for(const[x,y,z]of[[-.5,.8,-.4],[.5,1.2,.3],[0,1.6,-.1]])mk(new T3.BoxGeometry(.55,.55,.55),accent,x,y,z,g);}
  else if(id==='RELAY'){for(const x of[-.65,.65]){mk(new T3.CylinderGeometry(.18,.18,1.1,5),silver,x,1.1,0,g);mk(new T3.OctahedronGeometry(.35,0),accent,x,1.8,0,g);}mk(new T3.BoxGeometry(1.3,.15,.15),accent,0,1.5,0,g);}
 }else{
  const forms=[()=>mk(new T3.BoxGeometry(1.5,.8,.7),accent,0,1,0,g),()=>mk(new T3.TorusGeometry(.65,.16,4,8),accent,0,1,0,g),()=>mk(new T3.ConeGeometry(.65,1.3,4),accent,0,1.1,0,g),()=>mk(new T3.OctahedronGeometry(.7,0),accent,0,1.2,0,g),()=>mk(new T3.CylinderGeometry(.45,.45,1.4,6),accent,0,1.2,0,g),()=>mk(new T3.BoxGeometry(.4,1.5,1.1),accent,0,1.15,0,g)];
  forms[variant%forms.length]();const group=Math.floor(variant/6);if(group===1)for(const x of[-.9,.9])mk(new T3.BoxGeometry(.2,.7,.2),silver,x,1,0,g);if(group===2)mk(new T3.TorusGeometry(1,.07,3,10),silver,0,1,0,g).rotation.x=Math.PI/2;
 }
 for(let i=0;i<6;i++)if((variant+1)>>i&1)mk(new T3.BoxGeometry(.2,.12,.2),accent,-1+i*.4,.62,1,g);g.rotation.set(.65,-.5,0);return g;
}
function icon3dCircuitUrl(kind,id){if(kind==='skill'?!SKILLS[id]:!SUPPS[id])return '';return deviceThumb('circuit:'+kind+':'+id,()=>deviceCircuitModel(kind,id));}
function deviceResource(kind,size=28){const url=deviceThumb('resource:'+kind,()=>{const g=new T3.Group(),silver=m3('#b8c9d8'),dark=m3('#334358'),blue=m3('#80c5d2');if(kind==='parts'){for(const[x,y]of[[-.6,.2],[.5,.5],[0,-.5]])mk(new T3.BoxGeometry(1,.65,.7),silver,x,y,0,g);}else if(kind==='dust'){mk(new T3.OctahedronGeometry(1,0),blue,0,.2,0,g);mk(new T3.CylinderGeometry(1.2,1.2,.3,8),dark,0,-.8,0,g);}else{mk(new T3.BoxGeometry(2.2,.45,2),dark,0,0,0,g);mk(new T3.BoxGeometry(1.5,.25,1.3),blue,0,.35,0,g);for(const x of[-.7,0,.7])mk(new T3.BoxGeometry(.2,.2,.5),silver,x,0,1,g);}g.rotation.set(.5,-.5,0);return g;});return url?`<img src="${url}" alt="" width="${size}" height="${size}">`:'';}
function icon3dCollectibleUrl(kind,id){
 if(kind==='badge')return ACHS[id]?icon3dObjUrl('medal:'+['#8db7ef','#80cebd','#dac58d'][id.length%3]):'';
 if(kind!=='relic'||!RELICS[id])return '';
 return deviceThumb('relic:'+id,()=>{
  const g=new T3.Group(),metal=m3('#b9c9d6'),dark=m3('#334358'),cyan=m3('#80cebd'),amber=m3('#d4b374');
  if(id==='FAN'){mk(new T3.CylinderGeometry(.2,.3,1.5,6),metal,0,-.8,0,g);mk(new T3.TorusGeometry(1,.15,4,12),metal,0,.5,0,g);for(let i=0;i<3;i++)mk(new T3.BoxGeometry(.35,1.2,.15),cyan,Math.sin(i*2.094)*.4,.5+Math.cos(i*2.094)*.4,0,g).rotation.z=-i*2.094;}
  else if(id==='LENS'){mk(new T3.TorusGeometry(.8,.15,4,12),metal,0,.4,0,g);mk(new T3.CylinderGeometry(.65,.65,.15,10),cyan,0,.4,0,g).rotation.x=Math.PI/2;mk(new T3.BoxGeometry(.3,1.4,.3),dark,0,-.8,0,g);}
  else if(id==='DRINK'){mk(new T3.CylinderGeometry(.55,.6,1.8,8),cyan,0,0,0,g);mk(new T3.CylinderGeometry(.35,.35,.25,8),dark,0,1,0,g);mk(new T3.BoxGeometry(.8,.6,.1),metal,0,0,.55,g);}
  else if(id==='BATT'){for(const x of[-.6,.6]){mk(new T3.CylinderGeometry(.45,.45,1.8,8),metal,x,0,0,g);mk(new T3.CylinderGeometry(.47,.47,.4,8),dark,x,.7,0,g);mk(new T3.CylinderGeometry(.2,.2,.15,6),amber,x,1,0,g);}}
  else if(id==='VEST'){mk(new T3.BoxGeometry(1.6,2,.6),dark,0,0,0,g);for(const x of[-.4,.4])mk(new T3.BoxGeometry(.6,1.6,.2),metal,x,0,.4,g);}
  else if(id==='CALC'){mk(new T3.BoxGeometry(1.7,2.4,.4),metal,0,0,0,g);mk(new T3.BoxGeometry(1.3,.5,.1),cyan,0,.75,.25,g);for(const x of[-.5,0,.5])for(const y of[-.7,-.2,.25])mk(new T3.BoxGeometry(.3,.25,.1),dark,x,y,.27,g);}
  else if(id==='PIG'){mk(new T3.BoxGeometry(2,1.8,1.5),metal,0,0,0,g);mk(new T3.BoxGeometry(1.1,.06,.18),dark,0,.92,0,g);mk(new T3.CylinderGeometry(.45,.45,.12,10),amber,0,1.2,0,g).rotation.x=.6;}
  else if(id==='FOOD'){mk(new T3.BoxGeometry(2.2,.8,1.7),dark,0,0,0,g);for(const x of[-.5,.5])mk(new T3.BoxGeometry(.8,.25,1.2),x<0?metal:amber,x,.5,0,g);mk(new T3.BoxGeometry(.2,.12,2),cyan,0,.7,0,g);}
  else if(id==='BOMB'){mk(new T3.BoxGeometry(1.5,1.8,1.1),dark,0,0,0,g);mk(new T3.BoxGeometry(.5,.5,.2),amber,0,.2,.65,g);mk(new T3.TorusGeometry(.35,.07,4,8),metal,0,1.2,0,g);}
  else if(id==='SUN'){mk(new T3.OctahedronGeometry(.9,0),amber,0,.2,0,g);mk(new T3.TorusGeometry(1.3,.07,4,12),metal,0,.2,0,g).rotation.x=.8;mk(new T3.BoxGeometry(1.4,.25,1),dark,0,-1,0,g);}
  else{mk(new T3.BoxGeometry(1.3,1.7,.3),metal,0,0,0,g);mk(new T3.OctahedronGeometry(.45,0),cyan,0,0,.35,g);mk(new T3.TorusGeometry(.5,.04,4,10),dark,0,1,0,g);}
  g.rotation.set(.2,-.45,0);return g;
 });
}
function deviceSkillsHtml(){
 const connected=GridLab.resolve(G.board,G.lvl).filter(r=>r.wired).length;
 return `<div class="device-workspace device-skills"><div class="device-heading"><div><span class="device-eyebrow">技能接線</span><h3>${GridLab.layout(G.board).n}</h3><span>${GridLab.layout(G.board).size}×${GridLab.layout(G.board).size} 電路板</span></div><button class="mb" onclick="careerCircuits()">更換電路板${G.unread?.boards?.length?'<span class="play-new" data-board-badge>NEW</span>':''}</button></div>${playBoardSummary()}<section class="device-console" aria-label="技能組裝工作區">${wireTopHtml()}</section>${playPortStrip()}${wireSelCard()}<section class="device-inventory"><h3>技能與配件庫</h3><details class="device-caption"><summary>配件規則</summary><p>條件式配件的收益隨階級提升；同款條件只取最高階，傷害代價仍累計。供電及每技能三枚上限不變。</p></details>${uiInventoryHtml()}</section>${DIRECT_VIEW.builds?buildBar():''}<div class="direct-analysis-tools"><button class="mb" onclick="directBuildTools()">構築配置</button><button class="mb" onclick="directCombatReport()">戰鬥分析</button>${directHelpButton('skills')}</div></div>`;
}
function deviceMenuHtml(){
 const groups=[['遊戲',[['settings','遊戲設定','畫面與戰鬥'],['save','存檔備份','匯入與匯出']]],['進度',[['tutorial','操作入門',''],['goals','目標','里程碑獎勵'],['ach','成就','挑戰紀錄'],['dex','圖鑑','個人收藏進度'],['rank','排行榜','歷史構築']]],['資訊',[['log','更新日誌','版本紀錄'],['feedback','意見回饋','回報與建議'],['support','贊助',''],['wiki','編年史','完整機制參考']]]];
 return `<div class="device-workspace device-menu"><div class="device-directory" role="group" aria-label="設定與資料工具">${groups.flatMap(([group,items])=>items.map(([id,n,d])=>`<button class="mb device-directory-card" data-focus="directory-${id}" onclick="${id==='tutorial'?'onboardingResume()':id==='wiki'?'wikiOpen()':`openModal('${id}')`}">${id==='tutorial'?onboardingIcon():obj3d(id,48)}<b>${n}</b>${(id==='goals'&&dotOn('col'))||(id==='log'&&logNew())?'<i class="rd" aria-hidden="true"></i><span class="uxsr">有新內容</span>':''}</button>`)).join('')}</div>${secretArchiveHtml()}</div>`;
}
function deviceCraftHtml(){
 const slot=UI_WORK.craftSlot,it=G.equip[slot],act=UI_WORK.craftAct,operation=CRAFT[act],state=craftState(slot,act),result=CRAFT_RESULTS[slot];
 const slots=`<div class="device-equip-strip" role="group" aria-label="改機裝備">${Object.keys(SLOTN).map(k=>{const gear=G.equip[k];return `<button class="mb" data-focus="craftSlot-${k}" aria-pressed="${slot===k}" aria-label="${SLOTN[k]}，${gear?uxEsc(gear.name):'空欄位'}" onclick="uiWork('craftSlot','${k}')">${gear?.lg?xico('legend',gear.lg,36):eqico(k,gear?.r||0,36,gear)}<span>${SLOTN[k]}</span><small>${gear?RAR[gear.r].n:'空欄位'}</small></button>`;}).join('')}</div>`;
 const operations=`<div class="device-process-grid" role="group" aria-label="改機動作">${Object.entries(CRAFT).map(([key,op])=>{const s=key==='upgrade'&&it?.lg?coreRefineState(slot):craftState(slot,key),name=key==='upgrade'&&it?.lg?'核心重構':op.n;return `<button class="mb device-process" data-focus="craftAct-${key}" aria-pressed="${act===key}" onclick="uiWork('craftAct','${key}')"><b>${name}</b><span>${it?(s.ok?'可執行':s.reason):'先選裝備'}</span><small>${it&&s.cost!=null?(s.cost>0?s.cost+' 零件':s.ok?'免費':'—'):key==='upgrade'&&it?.lg?'零件 · 碎片 · 殘晶':'—'}</small></button>`;}).join('')}</div>`;
 let selected='<section class="device-craft-empty"><h3>放入一件裝備</h3><p>這個部位仍然空置。先到背包換裝，再回來改機。</p><button class="mb" onclick="openModal(\'warehouse\')">前往背包</button></section>';
 if(it){
  const rows=`<div class="device-affixes">${it.lg&&LEGEND_BY[it.lg]?`<div class="device-affix legend"><span>★</span><p>${uxEsc(LEGEND_BY[it.lg].d)}</p><span>專屬能力</span></div>`:''}<div class="device-affix implicit"><span>固定</span><p>${uxEsc(AFF[it.imp.k].t(it.imp.v))}</p><span>底材屬性</span></div>${it.aff.map((a,i)=>`<div class="device-affix ${it.lk===i?'locked':''}"><span>T${affTier(a,it.il)}</span><p>${uxEsc(AFF[a.k].t(a.v))}<small>${AFF[a.k].g==='s'?'副機位':'主機位'} · ${AFF[a.k].tags[0]} · 同階範圍 ${affRange(a,it).min}–${affRange(a,it).max}${a.v>affRange(a,it).max?' · 校準可能降低':''}</small></p><button class="mb" ${it.cr?'disabled':''} data-focus="craft-lock-${i}" aria-label="${it.lk===i?'解除鎖定':'鎖定'}${uxEsc(AFF[a.k].t(a.v))}" aria-pressed="${it.lk===i}" onclick="craftLock('${slot}',${i})">${it.lk===i?'已鎖':'鎖定'}</button></div>`).join('')||'<p class="device-caption">目前沒有額外詞綴，可先升級稀有度。</p>'}</div>`;
  const hero=`<div class="device-item-stage">${it.lg?xico('legend',it.lg,112):eqico(slot,it.r,112,it)}<div><span>${SLOTN[slot]} · ${rarityBadge(it.r)}</span><h3>${uxEsc(it.name)}</h3><span>物品等級 ${it.il} · ${it.lg?'傳奇':(SERIES[slot]?.[it.bs||0]?.n||'標準系')} · 詞綴 ${it.aff.length}／6${it.cr?' · 已腐化':''}</span></div></div>`;
  const execute=act==='upgrade'&&it.lg?coreRefineHtml(slot,it):`<div class="device-execute"><p>${operation.d}</p>${!state.ok?`<p id="craft-reason" class="uxwarning">${state.reason}</p>`:'<span id="craft-reason" hidden></span>'}<button class="mb pri" data-focus="craft-${slot}-${act}" aria-describedby="craft-reason" ${state.ok?'':'disabled'} onclick="craftDo('${slot}','${act}')">${act==='corrupt'?'查看腐化風險':operation.n} · ${state.cost} 零件</button>${act==='recal'?`<details class="device-details"><summary>指定詞綴升階</summary>${affTierHtml(slot,it)}</details>`:''}</div>`;
  selected=`<section class="device-craft-item" aria-label="選中裝備">${hero}${rows}</section><section class="device-craft-process"><h3>選擇工序</h3>${operations}${execute}${result&&result.it===it?`<div class="device-result" role="status"><strong>${uxEsc(result.msg)}</strong><span>消耗 ${result.cost} 零件</span><details><summary>查看變化</summary><p>之前：${uxEsc(result.before)}</p><p>之後：${uxEsc(result.after)}</p></details></div>`:''}</section>`;
 }
 return `<div class="device-workspace device-craft"><div class="device-heading"><div><span class="device-eyebrow">裝備改機</span><h3>街頭整備台</h3></div><button class="mb" onclick="openModal('warehouse')">背包 ↗</button></div><div class="device-wallet">${[['parts','零件',G.parts],['dust','核心殘晶',G.coreDust],['chips','電路點數',G.chips]].map(([key,n,v])=>`<div>${deviceResource(key)}<span>${n}<b>${tFmt(v||0)}</b></span></div>`).join('')}</div>${slots}${selected}${studioUtilitiesHtml()}</div>`;
}
