/* Direct manipulation and optional reading surfaces. Game data stays with existing owners. */
const DIRECT_VIEW={builds:false};
function uiTreeActivate(id){if(typeof PLAY_SUPPRESS!=='undefined'&&performance.now()<PLAY_SUPPRESS)return;if(!TREE[id])return;uiTreeSelect(id);if(canAllocateTalent(id))uiAllocateTalent(id);}
function directHelpButton(key){return `<button type="button" class="mb direct-help" aria-label="${{warehouse:'倉庫與保護規則',maps:'冒險說明',skills:'接線盤操作',tree:'天賦盤操作'}[key]||'說明'}" onclick="directHelp('${key}')">?</button>`;}
function directHelp(key){
 const copy={warehouse:['倉庫與保護規則',`普通裝備容量 ${whCap()} 件。核心每款收藏一件；穿著、上一件、構築引用、保管鎖定、詞綴鎖定與腐化物品受保護。滿倉或低於拾取門檻的裝備按原規則回收；累計回收 ${G.storageRecycled} 件。`],maps:['冒險與手記','全景可查看當前完整地圖，切回跟隨鏡頭繼續觀戰。手記記錄各地收錄的留言，可隨時重讀，不影響當前挑戰。'],skills:['接線盤操作','點終點裝技能，從電源拖線到同色終點。配件放在色塊位，線經過才生效，寶石只可入同色洞，每技能最多3枚配件，並消耗電路板供電。按住盤上機件可移位，同類可交換；拖出接線板邊框放開便會回庫存。也可點機件選「移動」，再點目標。無效位置及取消不改配置，操作後可復原。'],tree:['天賦盤操作','點可分配節點即加 1 點；已分配或未連接節點只顯示詳情。拖曳空白處平移，滾輪或雙指控制縮放，亦可用縮放與平移按鈕探索。方向鍵只移動焦點，Enter 或空格才執行；退回使用詳情的「退回 1 點」。']};
 const [name,text]=copy[key]||copy.skills;showOverlay(`<h2>${name}</h2><p>${uxEsc(text)}</p>${key==='maps'?'<div class="uxactions"><button class="mb" onclick="toggleWorldOverview();hideOverlay()">全景／跟隨鏡頭</button><button class="mb" onclick="directJournal()">電台手記</button></div>':key==='warehouse'?'<button class="mb" onclick="lootSources()">查看裝備來源</button>':''}<button class="mb" data-initial-focus onclick="hideOverlay()">關閉</button>`);
}
function directCharacterLinks(){return `<div class="direct-character-tools"><button class="mb" onclick="showDeathSummary()">死亡總結</button><button class="mb" onclick="openModal('warehouse')">配裝與核心</button><button class="mb" onclick="openModal('dress')">角色展示與裝扮</button><button class="mb" onclick="directCharacterStory()">職業資料</button><button class="mb" onclick="directEvents()">事件紀錄</button></div>`;}
function directCharacterStory(){const c=CHARS[G.char];showOverlay(`<h2>${uxEsc(c.n)}</h2><blockquote>「${uxEsc(c.quote)}」</blockquote>${c.story.map(t=>`<p>${uxEsc(t)}</p>`).join('')}<button class="mb" onclick="hideOverlay()">返回角色</button>`);}
function directEvents(){showOverlay(`<h2>事件紀錄</h2><ol class="log">${G.log.map(l=>`<li>${uxEsc(l.txt)}</li>`).join('')||'<li>尚無事件。</li>'}</ol><button class="mb" onclick="hideOverlay()">關閉</button>`);}
function directJournal(){showOverlay(`<h2>電台手記</h2>${storyJournalHtml()}${fieldJournalHtml()}<button class="mb" onclick="hideOverlay()">返回冒險</button>`);const d=$('ovl').querySelector('details');if(d)d.open=true;}
function directBuildTools(){DIRECT_VIEW.builds=!DIRECT_VIEW.builds;renderModal();}
function directCombatReport(){showOverlay(`<h2>戰鬥分析</h2>${dpsBar()}${uiResolvedHtml()}${uiCombatHtml()}<button class="mb" onclick="hideOverlay()">關閉</button>`);$('ui-combat-report').open=true;uiCombatRefresh();}

/* Portrait textures load asynchronously; update only their reserved image boxes. */
let DIRECT_PORTRAIT_TIMER=0;
function directPortraitMarkup(id,cls=''){
 const url=icon3dPortraitUrl(id);if(!url&&!DIRECT_PORTRAIT_TIMER)DIRECT_PORTRAIT_TIMER=setTimeout(()=>directPortraitsRefresh(0),100);
 return `<span class="direct-portrait ${cls}" data-direct-portrait="${id}" role="img" aria-label="${uxEsc(CHARS[id].n)}">${url?`<img src="${url}" alt="">`:`<span class="portrait-wait">${uxEsc(CHARS[id].n.split(' ').at(-1))}</span>`}</span>`;
}
function directPortraitsRefresh(attempt=0){
 clearTimeout(DIRECT_PORTRAIT_TIMER);DIRECT_PORTRAIT_TIMER=0;let pending=false;
 document.querySelectorAll('[data-direct-portrait]').forEach(el=>{const id=el.dataset.directPortrait;if(!Object.hasOwn(CHARS,id))return;const url=icon3dPortraitUrl(id);if(url){if(!el.querySelector('img'))el.innerHTML=`<img src="${url}" alt="">`;}else pending=true;});
 if(pending&&attempt<60&&!ICON3D.fail)DIRECT_PORTRAIT_TIMER=setTimeout(()=>directPortraitsRefresh(attempt+1),150);
}

/* A first-run gate: never set by importing an existing save and never grants all characters. */
const INTRO_KEY='idle-hero-intro-v1',INTRO={active:false,step:0,selected:'street',name:''};
const INTRO_STORY=[
 ['下午三點的錯頻','夏日街區還在過它平常的一天。小禾忙著修風扇，阿澄的渡船剛靠岸。街角電台卻突然播出一段沒有人點過的旋律。'],
 ['走錯頻道的街頭器材','販賣機開始找錯零，音箱、拖板和速遞車也跟著旋律亂跑。小禾發現，異常訊號正沿著舊電纜往高架橋的另一頭傳。先把前街清出一條路，再找出那段聲音從哪裡來。'],
 ['把街區接回來','阿澄在港口等你的消息，小禾留在電台接應。帶上熟悉的裝置，從前街開始追查。選擇你的職業，以自己的名字，把街區的聲音一段段接回來。']
];
function introPersist(){try{localStorage.setItem(INTRO_KEY,JSON.stringify({step:INTRO.step,cover:INTRO.cover===true,selected:INTRO.selected,name:INTRO.name}));}catch(e){}}
function introStart(reset=false){INTRO.active=true;INTRO.cover=true;G.paused=true;try{const d=reset?null:JSON.parse(localStorage.getItem(INTRO_KEY));if(d){INTRO.cover=d.cover===true;INTRO.step=Math.max(0,Math.min(3,d.step|0));if(Object.hasOwn(CHARS,d.selected))INTRO.selected=d.selected;INTRO.name=typeof d.name==='string'?d.name.slice(0,12):'';}}catch(e){}document.body.classList.add('intro-active');introRender();}
function introStep(n){if(!INTRO.active)return;INTRO.cover=false;introLogoDispose();INTRO.step=Math.max(0,Math.min(3,n));introPersist();introRender();}
function introChoose(id){if(!INTRO.active||!Object.hasOwn(CHARS,id))return;INTRO.selected=id;introPersist();introRender();}
function introEscape(){if(INTRO.cover){introStep(0);return;}if(INTRO.step<3)introStep(3);else uxAnnounce('選一位角色，再按開始冒險。');}
function introRender(){
 if(INTRO.cover){introCoverRender();return;}introLogoDispose();
 const choose=INTRO.step===3,c=CHARS[INTRO.selected],portrait=choose?icon3dPortraitUrl(INTRO.selected):'',[title,text]=INTRO_STORY[Math.min(INTRO.step,2)],o=$('ovl');
 o.innerHTML=`<div class="mbox intro-shell"><div class="intro-top"><span class="intro-channel">${choose?'CLASS SELECT':'RADIO / 電台前街'}</span><div class="intro-sky" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div>${choose?`${directPortraitMarkup(INTRO.selected,'intro-portrait')}<div class="intro-cover"><span>${uxEsc(c.title)}</span><strong>${uxEsc(c.n.split(' ').at(-1))}</strong></div>`:`${introStoryArt(INTRO.step)}<strong class="intro-scene-title">${uxEsc(title)}</strong>`}</div><div class="intro-hinge" aria-hidden="true"></div><div class="intro-bottom">${choose?`<h2>選擇職業</h2><label class="career-name" for="intro-name">玩家名稱<input id="intro-name" maxlength="12" autocomplete="off" value="${uxEsc(INTRO.name)}" placeholder="輸入1至12字" oninput="INTRO.name=this.value;introPersist()"></label><p id="intro-name-error" role="alert"></p><div class="intro-choices" role="group" aria-label="起始職業">${Object.entries(CHARS).map(([id,k])=>`<button class="mb intro-choice" data-intro-char="${id}" aria-pressed="${INTRO.selected===id}" onclick="introChoose('${id}')">${directPortraitMarkup(id)}<span>${uxEsc(k.n)}<small>${uxEsc(k.title)}</small></span></button>`).join('')}${[1,2].map(()=>'<div class="intro-future" aria-label="未來職業，尚未開放"><b>？？？</b><small>尚未開放</small></div>').join('')}</div><div class="intro-role"><p>${uxEsc(c.role)}</p><p><b>${uxEsc(c.sig.n)}</b> · ${uxEsc(c.sig.d)}</p></div><div class="intro-controls"><button class="mb" onclick="introStep(2)">返回故事</button><button class="mb pri" data-initial-focus onclick="introBegin()">以${uxEsc(c.n)}開始冒險</button></div><p class="intro-footnote">職業創立後固定；可在角色列表另開角色。每個角色獨立保存進度。${PROFILE_SESSION.pending?'<button class="mb" onclick="profileCancelNew()">返回原角色</button>':''}</p>`:`<div class="intro-dialogue"><span>電台記錄 · ${INTRO.step+1}／3</span><h2>${uxEsc(title)}</h2><p>${uxEsc(text)}</p></div><div class="intro-controls"><button class="mb" onclick="introStep(3)">略過故事</button>${INTRO.step?'<button class="mb" onclick="introStep(INTRO.step-1)">上一頁</button>':''}<button class="mb pri" data-initial-focus onclick="introStep(INTRO.step+1)">${INTRO.step===2?'選擇角色':'下一頁'}</button></div>`}</div></div>`;
 uxOpenDialog(o,choose?'選擇職業':'冒險序章',introEscape);
}
function introBegin(){if(!INTRO.active||INTRO.step!==3||!Object.hasOwn(CHARS,INTRO.selected))return;const name=String(INTRO.name||'').trim();if(!name||name.length>12){const error=$('intro-name-error');if(error)error.textContent='請先輸入1至12字的玩家名稱。';$('intro-name')?.focus();return;}G.startingChar=INTRO.selected;G.char=INTRO.selected;G.heroName=name;recalc();G.h.hp=G.st.life;INTRO.active=false;G.paused=false;G.lastWall=Date.now();document.body.classList.remove('intro-active');uxCloseDialog($('ovl'));try{localStorage.removeItem(INTRO_KEY);}catch(e){}G.userCz=false;G.cz=1;GAME_VIEW.prefs.hideBattle=false;viewSavePrefs();onboardingStart(true);const saved=saveGame();openModal('char');viewApplyPrefs();uxAnnounce(saved?'冒險開始，角色已保存。':'本機保存失敗。');if(!saved)showOverlay(`<h2>暫時無法保存進度</h2><p>角色已開始冒險，但瀏覽器未能保存。離開前請先匯出存檔碼，避免遺失進度。</p><button class="mb pri" data-initial-focus onclick="hideOverlay();openModal('save')">匯出備份</button><button class="mb" onclick="hideOverlay()">繼續遊戲</button>`);}

