function ascensionIconUrl(id){
 const col={ground:'#e8934a',arc:'#e8934a',drive:'#e8934a',echo:'#4fc6bd',still:'#4fc6bd',pace:'#4fc6bd',snipe:'#8d80ea',split:'#8d80ea',shadow:'#8d80ea',dual:'#63c982',repair:'#63c982',melt:'#63c982'}[id]||'#88c8df';
 return deviceThumb('asc:'+id,()=>{
  const g=new T3.Group(),A=m3(col),D=m3('#334358'),S=m3('#cfd9e8'),B=(w,h,d,m,x,y,z,rx=0,ry=0,rz=0)=>{const o=mk(new T3.BoxGeometry(w,h,d),m,x,y,z,g);o.rotation.set(rx,ry,rz);return o;};
  mk(new T3.CylinderGeometry(1.35,1.5,.3,10),D,0,-1.45,0,g);mk(new T3.CylinderGeometry(1.15,1.15,.15,10),S,0,-1.25,0,g);
  if(id==='ground'){mk(roundedG(2.2,2.6,.6),A,0,.1,0,g);B(.5,1.3,.7,S,0,.2,0);B(1.3,.4,.7,S,0,.4,0);}
  else if(id==='arc'){B(.7,1.7,.6,A,.35,.8,0,0,0,.45);B(.7,1.7,.6,A,-.35,-.5,0,0,0,.45);B(1.5,.5,.6,A,0,.15,0);}
  else if(id==='drive'){mk(new T3.ConeGeometry(1.2,2,4),A,0,.3,0,g).rotation.set(0,Math.PI/4,-Math.PI/2);B(1.4,.7,.7,S,-1.3,.3,0);}
  else if(id==='echo'){for(const[r,y]of[[1.5,-.4],[1.05,.1],[.55,.6]])mk(new T3.TorusGeometry(r,.2,6,16),A,0,y,0,g).rotation.x=Math.PI/2;}
  else if(id==='still'){mk(new T3.OctahedronGeometry(1.2,0),A,0,.3,0,g);mk(new T3.TorusGeometry(1.7,.14,6,18),S,0,.3,0,g).rotation.x=Math.PI/2;}
  else if(id==='pace'){for(const x of[-1.2,0,1.2]){const o=mk(new T3.ConeGeometry(.9,1.1,3),A,x,.2,0,g);o.rotation.z=-Math.PI/2;o.scale.z=.5;}}
  else if(id==='snipe'){mk(new T3.TorusGeometry(1.3,.2,6,18),A,0,.2,0,g);B(3.2,.22,.4,S,0,.2,0);B(.22,3.2,.4,S,0,.2,0);mk(new T3.SphereGeometry(.25,8,6),m3('#ffffff'),0,.2,0,g);}
  else if(id==='split'){mk(new T3.SphereGeometry(.8,8,6),A,-.9,.2,0,g);for(const y of[-.7,.2,1.1])mk(new T3.SphereGeometry(.42,8,6),S,1.1,y,0,g);B(1.3,.2,.3,S,.1,.2,0);}
  else if(id==='shadow'){for(let i=0;i<3;i++)B(1.5,2.1,.4,i?m3(i===1?'#6a62b8':'#4a4486'):A,i*.9-.9,.2,i*-.5);}
  else if(id==='dual'){for(const x of[-.85,.85]){B(1.3,2.3,.5,A,x,.2,0);B(.9,1.2,.1,S,x,.55,.3);}}
  else if(id==='repair'){B(.9,2.6,.7,A,0,.2,0);B(2.6,.9,.7,A,0,.2,0);}
  else{mk(new T3.IcosahedronGeometry(1.2,0),A,0,.3,0,g);for(const x of[-1.2,1.2])mk(new T3.SphereGeometry(.35,8,6),S,x,-.6,0,g);}
  g.rotation.set(.35,-.5,0);return g;});
}
/* Career, profile and board actions extend the existing dialog and preview owners. */
const CAREER_UI={pending:null,node:null};
function careerProfiles(){
 const profiles=PROFILE_SESSION.profiles,blocked=!!G.run||!!G.train;
 showOverlay(`<h2>角色列表</h2><p>職業在創立後固定，切換的是獨立角色；各自保存裝備、電路板與進度。只有啟用的角色獲得離線收益。</p><div class="career-profile-grid">${profiles.map(p=>`<button class="mb career-profile" ${blocked||p.id===PROFILE_SESSION.active?'disabled':''} onclick="careerSwitch('${p.id}')">${directPortraitMarkup(p.save.char)}<span>${uxEsc(p.save.heroName||'未命名')}<small>${CHARS[p.save.char].n} · Lv. ${p.save.lvl}</small><small>${p.id===PROFILE_SESSION.active?'目前角色':'切換至此角色'}</small></span></button>`).join('')}</div>${blocked?'<p>先結束挑戰或訓練，再切換角色。</p>':''}<div class="uxactions"><button class="mb" data-initial-focus onclick="hideOverlay()">返回</button><button class="mb pri" ${blocked||profiles.length>=PROFILE_MAX?'disabled':''} onclick="careerNew()">建立新角色 · ${profiles.length}／${PROFILE_MAX}</button></div><p>不會刪除任何已有角色；備份存檔碼保存目前角色。</p>`);
}
function careerSwitch(id){if(!profileSwitch(id)){uxAnnounce('目前不能切換，或保存失敗；角色未變更。');return;}hideOverlay();openModal('char');uxAnnounce('已切換角色：'+G.heroName+'。');}
function careerNew(){if(!profileNew()){uxAnnounce('請先結束挑戰、確認角色空位及保存狀態。');return;}}
function careerAscensionSummary(){const a=ascendInfo();return `<section class="career-asc-summary"><div><span>${CHARS[G.char].n}</span><h3>${a?a.n:'尚未昇華'}</h3><p>${a?a.d:'Lv20、最深8層及討伐10次BOSS後，可選擇一條昇華。'}</p></div><button class="mb" data-focus="ascension-open" onclick="${a?'careerAscensionTalents()':'careerAscensions()'}">${a?'昇華天賦':'選擇昇華'}</button></section>`;}
function careerAscensions(){
 const ready=canAscend();showOverlay(`<h2>${CHARS[G.char].n} · 昇華</h2><p>同一職業的三條道路，技能與配件仍自由配搭。首次免費，重選花費等級×500金幣；不能改變基礎職業。</p>${ready?'':`<p class="uxwarning">條件：Lv20（目前${G.lvl}）、最深8層（目前${G.maxDepth}）、BOSS10次（目前${G.bossKills}）。</p>`}<div class="career-asc-grid">${ASCENSIONS[G.char].map(a=>{const state=ascensionState(a.id);return `<article class="career-asc-card${G.ascension===a.id?' selected':''}"><span class="career-asc-mark" aria-hidden="true">${ascensionIconUrl(a.id)?`<img src="${ascensionIconUrl(a.id)}" alt="" width="64" height="64">`:''}</span><h3>${a.n}</h3><p>${a.d}</p><button class="mb" ${G.ascension===a.id||state.ok?'':'disabled'} onclick="${G.ascension===a.id?'careerAscensionTalents()':`careerAskAscension('${a.id}')`}">${G.ascension===a.id?'目前昇華 · 配置天賦':!ready?'未達條件':state.cost?'重選 · '+tFmt(state.cost)+' 金幣':'選擇此昇華'}</button></article>`}).join('')}</div><button class="mb" data-initial-focus onclick="hideOverlay()">返回角色</button>`);
}
function careerAskAscension(id){const s=ascensionState(id);if(!s.ok)return;CAREER_UI.pending={job:G.char,profile:PROFILE_SESSION.active,prev:G.ascension||null,id,cost:s.cost};showOverlay(`<h2>${s.cost?'重選':'選擇'}${s.a.n}？</h2><p>${s.a.d}</p><p>${s.cost?'花費 '+tFmt(s.cost)+' 金幣。':'首次選擇免費。'}基礎職業保持${CHARS[G.char].n}。${G.ascensionNodes?.length?`目前${G.ascensionNodes.length}個昇華天賦會退回點數，新的昇華需自行重新分配。`:""}</p><div class="uxactions"><button class="mb" data-initial-focus onclick="hideOverlay()">取消</button><button class="mb pri" onclick="careerConfirmAscension()">確認昇華</button></div>`);}
function careerConfirmAscension(){const p=CAREER_UI.pending;CAREER_UI.pending=null;if(!p||p.profile!==PROFILE_SESSION.active||!chooseAscension(p.id,p)){uxAnnounce('條件或角色已改變，未扣款。');return;}hideOverlay();renderModal();saveGame();uxAnnounce('已選擇'+ascendInfo().n+'。');}
function careerBoardMini(id){const L=GridLab.layout({template:id}),colors={r:'var(--ux-signal-red)',b:'var(--ux-signal-blue)',g:'var(--ux-signal-green)'};return `<div class="career-board-mini" style="grid-template-columns:repeat(${L.size},1fr)" aria-hidden="true">${Array.from({length:L.size**2},(_,i)=>{const x=i%L.size+1,y=Math.floor(i/L.size)+1,c=GridLab.padColor(x,y,{template:id});return `<i style="--hole:${colors[c]||'var(--ux-ink)'}"></i>`}).join('')}</div>`;}
function careerCircuits(){showOverlay(`<h2>電路板收藏</h2><p>新板先為空白；再次換回可讀取你先前手動保存的配置。所有配件仍由同一庫存及供電限制驗證。</p><div class="career-board-grid">${Object.entries(GridLab.TEMPLATES).filter(([id,t])=>!t.legacy||G.circuits.includes(id)).map(([id,t])=>{const owned=G.circuits.includes(id),current=G.board.template===id,ok=owned&&circuitAllowed(id)&&!G.run&&!G.train&&!current;return `<button class="mb career-board-card" ${ok?'':'disabled'} onclick="careerEquipCircuit('${id}')">${careerBoardMini(id)}<b>${t.n}${playNewBadge('boards',id)}</b><span>${t.size}×${t.size} · ${GridLab.layout({template:id}).socks.length}終點 · 供電${t.power}</span>${t.note?`<span class="career-board-note">${t.note}</span>`:''}<small>${current?'使用中':owned?'已持有':`Lv${t.lvl}／最深${t.depth}層後掉落`}</small></button>`}).join('')}</div><p>符合條件後，最多三次BOSS討伐會保底掉落一塊未持有板。需走近拾取；不會自動裝備。</p><button class="mb" data-initial-focus onclick="hideOverlay()">返回技能盤</button>`);noticeRead('boards');document.querySelector('[data-board-badge]')?.remove();}
function careerEquipCircuit(id){if(!equipCircuit(id)){uxAnnounce('目前不能換板，原配置保留。');return;}held=null;selPiece=null;selSock=-1;WIRE_UNDO=null;WIRE_MOVE=null;hideOverlay();renderModal();uxAnnounce('已手動換用'+GridLab.layout(G.board).n+'。');}
function careerImportOther(raw){CAREER_UI.pending={import:raw};showOverlay(`<h2>另存為新角色？</h2><p>這份存檔是${CHARS[raw.char]?.n||'未知職業'}，不會改變目前角色的職業。確認後會用新角色欄位保留它。</p><div class="uxactions"><button class="mb" data-initial-focus onclick="hideOverlay()">取消</button><button class="mb pri" onclick="careerConfirmImport()">新增角色並匯入</button></div>`);}
function careerConfirmImport(){const raw=CAREER_UI.pending?.import;CAREER_UI.pending=null;if(!raw||!profileImportNew(raw)){uxAnnounce('未能匯入，請確認存檔、角色空位及保存狀態。');return;}hideOverlay();openModal('char');}
function careerAscensionTalents(){
 CAREER_UI.pending=null;const asc=ascendInfo();if(!asc){careerAscensions();return;}
 const nodes=ASC_TALENTS[G.ascension],chosen=nodes.find(n=>n.id===CAREER_UI.node),used=G.ascensionNodes?.length||0,budget=ascensionBudget();
 const nodeButton=n=>{const state=ascensionNodeState(n.id),status=state.selected?'已分配':state.allocate?'點此分配':n.parent&&!G.ascensionNodes?.includes(n.parent)?'需先分配前置節點':used>=budget?'點數已用完':'暫不能分配';return `<button class="mb asc-node${n.parent?' core':''}${state.selected?' allocated':''}${CAREER_UI.node===n.id?' inspecting':''}" data-asc-node="${n.id}" data-focus="asc-node-${n.id}" aria-pressed="${!!state.selected}" aria-label="${uxEsc(n.n)}，${status}" onclick="careerNodeClick('${n.id}')"><span class="asc-node-mark" aria-hidden="true">${n.parent?'◆':'▪'}</span><b>${n.n}</b><small>${status}</small>${playAscensionDescription(n)}</button>`;};
 showOverlay(`<h2>${asc.n} · 昇華天賦</h2><section class="asc-meaning"><b>這條昇華改變什麼？</b><p>${uxEsc(asc.d)}</p><small>下面每個節點直接列出實際效果；四點預算需要選擇，點可分配節點便會投入。</small></section><div class="asc-budget"><b id="asc-point-count">可用 ${Math.max(0,budget-used)}／${budget} 點</b><button class="mb" data-focus="ascension-reselect" onclick="careerAscensions()">重選昇華</button></div><p class="asc-hint">金幣 <span id="asc-wallet">${tFmt(G.gold)}</span>。每支先選小天賦，再選特色核心。最多4點，不能取得全部分支。Lv30／最深12層、Lv40／最深18層各多1點。</p>${G.run||G.train?'<p class="uxwarning">先結束挑戰或訓練，再分配或退還昇華天賦。</p>':''}<div class="asc-branches">${nodes.filter(n=>!n.parent).map(root=>`<section class="asc-branch" aria-label="${root.n}分支">${nodeButton(root)}<span class="asc-connector" aria-hidden="true"></span>${nodeButton(nodes.find(n=>n.parent===root.id))}</section>`).join('')}</div><section class="asc-node-detail" id="asc-node-detail" aria-live="polite">${chosen?`<h3>${chosen.n}</h3><p>${chosen.d}</p>${chosen.parent?`<p>前置：${nodes.find(n=>n.id===chosen.parent).n}</p>`:''}${G.ascensionNodes?.includes(chosen.id)?`<button class="mb" data-asc-refund="${chosen.id}" ${ascensionNodeState(chosen.id).refund&&G.gold>=25*G.lvl?'':'disabled'} onclick="careerAskNodeRefund('${chosen.id}')">退還此點 · ${tFmt(25*G.lvl)} 金幣</button>${!ascensionNodeState(chosen.id).refund?'<p>需先退還下方核心，或結束挑戰。</p>':''}`:'<p>點可分配節點即加1點；點已分配節點查看詳情。</p>'}`:'<p>點選節點，查看效果及前置條件。</p>'}</section><button class="mb" data-asc-reset ${used&&!G.run&&!G.train&&G.gold>=25*G.lvl*used?'':'disabled'} onclick="careerAskNodeRefund(null)">全部退點 · ${tFmt(25*G.lvl*used)} 金幣</button><p class="asc-hint">每點退還成本：等級×25金幣；不改一般天賦、職業或裝備。</p>`,{close:careerAscensions,closeLabel:'關閉昇華天賦，返回昇華選擇',surface:'ascension-window'});
}
function careerTalentRefresh(){const wallet=$('asc-wallet');if(!wallet)return;wallet.textContent=tFmt(G.gold);const used=G.ascensionNodes?.length||0,budget=ascensionBudget();$('asc-point-count').textContent='可用 '+Math.max(0,budget-used)+'／'+budget+' 點';const reset=document.querySelector('[data-asc-reset]');if(reset){reset.disabled=!used||!!G.run||!!G.train||G.gold<25*G.lvl*used;reset.textContent='全部退點 · '+tFmt(25*G.lvl*used)+' 金幣';}const refund=document.querySelector('[data-asc-refund]');if(refund){refund.disabled=!ascensionNodeState(refund.dataset.ascRefund).refund||G.gold<25*G.lvl;refund.textContent='退還此點 · '+tFmt(25*G.lvl)+' 金幣';}}
function careerNodeClick(id){const state=ascensionNodeState(id);if(!state.n)return;CAREER_UI.node=id;const allocated=allocateAscensionNode(id);careerAscensionTalents();requestAnimationFrame(()=>document.querySelector(`[data-asc-node="${id}"]`)?.focus({preventScroll:true}));if(allocated){const saved=saveGame();uxAnnounce('已分配'+state.n.n+'，剩餘'+(ascensionBudget()-G.ascensionNodes.length)+'點。'+(saved?'':'本機未能保存，請先匯出備份。'));}}
function careerAskNodeRefund(id){const nodes=G.ascensionNodes||[],cost=25*G.lvl*(id?1:nodes.length);if(!nodes.length||G.run||G.train||G.gold<cost||id&&!ascensionNodeState(id).refund)return;CAREER_UI.pending={nodeRefund:{id,asc:G.ascension,cost,nodes:JSON.stringify(nodes),profile:PROFILE_SESSION.active}};showOverlay(`<h2>${id?'退還此點':'全部退點'}？</h2><p>花費${tFmt(cost)}金幣，${id?'退還所選末端天賦':'退還全部昇華天賦'}。一般天賦、職業、昇華及裝備保留。</p><div class="uxactions"><button class="mb" data-initial-focus onclick="careerAscensionTalents()">取消</button><button class="mb pri" onclick="careerConfirmNodeRefund()">確認退點</button></div>`,{close:careerAscensionTalents});}
function careerConfirmNodeRefund(){const p=CAREER_UI.pending?.nodeRefund;CAREER_UI.pending=null;if(!p||p.profile!==PROFILE_SESSION.active)return;const success=p.id?refundAscensionNode(p.id,p):resetAscensionNodes(p);careerAscensionTalents();if(success){const saved=saveGame();uxAnnounce('已退還昇華天賦點數。'+(saved?'':'本機未能保存，請先匯出備份。'));}else uxAnnounce('條件已改變，未退點或扣款。');}
