(function(){const style=document.createElement('style');style.textContent=READABILITY_CSS;document.head.append(style);addEventListener('resize',()=>{if(modalTab==='tree'&&TALENT_VIEW.fit){TALENT_VIEW.zoom=null;TALENT_VIEW.left=null;TALENT_VIEW.top=null;renderModal();}});})();

