/* Inventory lifecycle extends the canonical single-item recycler and overlay. */
const LOOT_UI={rar:[0,1],slots:Object.keys(SLOTN),maxLevel:9999,junk:false,preserveTop:true,saveFailed:false,pending:null,result:null};
function gearProtection(it){return it.lg?'核心收藏':Object.values(G.equip).includes(it)?'穿著中':Object.values(G.equipBackup).includes(it)?'上一件':it.kept?'保管鎖定':it.lk!=null?'詞綴鎖定':it.cr?'已腐化':gearReferenced(it)?'構築引用':'';}
function lootMatches(it,filter=LOOT_UI){return !gearProtection(it)&&filter.rar.includes(it.r)&&filter.slots.includes(it.slot)&&it.il<=filter.maxLevel&&(!filter.junk||it.junk===true)&&(!filter.preserveTop||!it.aff.some(a=>affTier(a,it.il)<=1));}
function lootCandidates(filter=LOOT_UI){return G.inventory.filter(it=>lootMatches(it,filter));}
function lootTotals(items){return {count:items.length,gold:items.reduce((n,it)=>n+itemValue(it),0),parts:items.reduce((n,it)=>n+[1,2,5,12][it.r],0)};}
function lootStorageToolsHtml(){
 const safe=G.inventory.filter(it=>!gearProtection(it)).length,pct=Math.round(G.inventory.length/whCap()*100);
 return `<section class="loot-manager" aria-label="背包整理"><div class="loot-capacity"><b>背包 ${G.inventory.length}／${whCap()}</b><span>${safe} 件可處理 · ${G.inventory.length-safe} 件保護中</span><meter min="0" max="${whCap()}" value="${G.inventory.length}" aria-label="背包使用量">${pct}%</meter></div><div class="uxactions"><button class="mb pri" data-focus="loot-clean" onclick="lootCleanupOpen()">篩選分解</button><button class="mb" onclick="lootManageRules()">容量與拾取</button><button class="mb" onclick="directBuildTools()">構築保管</button></div>${LOOT_UI.result?`<p class="loot-result" role="status">${uxEsc(LOOT_UI.result)}</p>`:''}${LOOT_UI.saveFailed?'<div class="uxwarning" role="alert">變更仍在目前畫面，尚未保存。請先匯出備份，避免關閉分頁後遺失。<div class="uxactions"><button class="mb" onclick="openModal(\'save\')">匯出備份</button><button class="mb" onclick="lootRetrySave()">重試保存</button></div></div>':''}</section>`;
}
function lootCleanupOpen(focusKey=null){
 const scroll=document.querySelector('#ovl .mbox')?.scrollTop||0;
 const items=lootCandidates(),tot=lootTotals(items),rar=RAR.slice(0,3).map((r,i)=>`<label><input data-focus="loot-rar-${i}" type="checkbox" ${LOOT_UI.rar.includes(i)?'checked':''} onchange="lootFilterToggle('rar',${i})">${r.n}</label>`).join(''),slots=Object.entries(SLOTN).map(([id,n])=>`<label><input data-focus="loot-slots-${id}" type="checkbox" ${LOOT_UI.slots.includes(id)?'checked':''} onchange="lootFilterToggle('slots','${id}')">${n}</label>`).join('');
 showOverlay(`<h2 class="uxdialog-title">篩選分解</h2><p>篩選整個背包，並非只有目前這一頁。核心收藏不會加入分解。</p><fieldset class="loot-filter"><legend>稀有度</legend>${rar}</fieldset><fieldset class="loot-filter"><legend>部位</legend>${slots}</fieldset><label class="loot-level" for="loot-max">物品等級上限<input id="loot-max" type="number" min="1" max="9999" value="${LOOT_UI.maxLevel}" onchange="lootLevel(this.value)"></label><label class="loot-check"><input type="checkbox" ${LOOT_UI.junk?'checked':''} onchange="lootJunk(this.checked)" data-focus="loot-junk">只分解已標記待拆的裝備</label><label class="loot-check"><input type="checkbox" ${LOOT_UI.preserveTop?'checked':''} data-focus="loot-top" onchange="lootTop(this.checked)">保留含 T0／T1 詞綴的裝備</label><section class="loot-preview" aria-label="分解收益預覽"><strong>${tot.count}<small>件符合</small></strong><span>金幣 +${tot.gold}<br>零件 +${tot.parts}</span></section><p class="uxmeta">穿著、上一件、構築引用、保管／詞綴鎖定及已腐化物品一律略過。單件詳情可標記待拆或鎖定。</p><details><summary>查看符合物品（${items.length}）</summary><div class="loot-preview-grid">${items.slice(0,36).map(it=>`<span>${eqico(it.slot,it.r,32,it)}${uxEsc(it.name)}<small>Lv. ${it.il}</small></span>`).join('')||'<p>沒有符合物品，調整篩選即可。</p>'}${items.length>36?`<p>另有 ${items.length-36} 件，確認前將列出總數。</p>`:''}</div></details><div class="uxactions"><button class="mb" data-initial-focus onclick="hideOverlay()">保留裝備</button><button class="mb pri" ${items.length?'':'disabled'} onclick="lootCleanupAsk()">分解這 ${items.length} 件…</button></div>`);
 if(focusKey){const box=document.querySelector('#ovl .mbox');if(box)box.scrollTop=scroll;const target=document.querySelector('[data-focus="'+focusKey+'"]');if(target){document.querySelector('#ovl [data-initial-focus]')?.removeAttribute('data-initial-focus');target.setAttribute('data-initial-focus','');target.focus({preventScroll:true});}}
}
function lootFilterToggle(key,value){if(!['rar','slots'].includes(key))return;const a=LOOT_UI[key];LOOT_UI[key]=a.includes(value)?a.filter(v=>v!==value):[...a,value];lootCleanupOpen('loot-'+key+'-'+value);}
function lootTop(value){LOOT_UI.preserveTop=value;lootCleanupOpen('loot-top');}
function lootJunk(value){LOOT_UI.junk=value;lootCleanupOpen('loot-junk');}
function lootLevel(value){LOOT_UI.maxLevel=Math.max(1,Math.min(9999,Math.floor(Number(value)||1)));lootCleanupOpen();}
function lootCleanupAsk(){
 const items=lootCandidates();if(!items.length)return lootCleanupOpen();const totals=lootTotals(items);LOOT_UI.pending={filter:{rar:[...LOOT_UI.rar],slots:[...LOOT_UI.slots],maxLevel:LOOT_UI.maxLevel,junk:LOOT_UI.junk,preserveTop:LOOT_UI.preserveTop},items:items.map(it=>({id:it.uid,stamp:JSON.stringify(it)})),profile:typeof PROFILE_SESSION!=='undefined'?PROFILE_SESSION.active:null};
 showOverlay(`<h2 class="uxdialog-title">分解 ${totals.count} 件裝備？</h2><div class="loot-preview"><strong>+${totals.parts}<small>零件</small></strong><span>金幣 +${totals.gold}<br>騰出 ${totals.count} 格</span></div><p>物品會永久消失，不能還原。只處理剛才預覽的物品，後來拾取的裝備不會加入；狀態改變或新增保護會略過。</p><div class="uxactions"><button class="mb" data-initial-focus onclick="LOOT_UI.pending=null;lootCleanupOpen()">返回篩選</button><button class="mb pri" onclick="lootCleanupConfirm()">確認分解 ${totals.count} 件</button></div>`);
}
function lootCleanupConfirm(){
 const pending=LOOT_UI.pending;LOOT_UI.pending=null;if(!pending)return;
 if(typeof PROFILE_SESSION!=='undefined'&&pending.profile!==PROFILE_SESSION.active){uxAnnounce('目前角色已改變，沒有分解。');return;}
 let count=0,parts=0,gold=0;for(const entry of pending.items){const it=G.inventory.find(x=>x.uid===entry.id);if(!it||JSON.stringify(it)!==entry.stamp||!lootMatches(it,pending.filter))continue;const value=itemValue(it),part=[1,2,5,12][it.r];if(recycleStored(it.uid)){count++;gold+=value;parts+=part;}}
 LOOT_UI.result=`已分解 ${count} 件，獲得 ${gold} 金幣、${parts} 零件；略過 ${pending.items.length-count} 件。`;LOOT_UI.saveFailed=!saveGame();hideOverlay();renderModal();document.querySelector('[data-focus="loot-clean"]')?.focus();uxAnnounce(LOOT_UI.result+(LOOT_UI.saveFailed?'尚未保存，請先匯出備份。':''));
}
function lootRetrySave(){LOOT_UI.saveFailed=!saveGame();renderModal();document.querySelector('[data-focus="loot-clean"]')?.focus();uxAnnounce(LOOT_UI.saveFailed?'仍未能保存，請先匯出備份。':'已保存目前進度，沒有重複分解。');}
function lootMark(uid){const it=G.inventory.find(x=>x.uid===uid);if(!it)return;it.junk=!it.junk;G.dirty=true;G.inventoryRevision++;uiInspectGear(uid);uxAnnounce(it.junk?'已標記待拆；仍須確認才分解。':'已移除待拆標記。');}
function lootManageRules(){showOverlay(`<h2 class="uxdialog-title">容量與拾取</h2><p>背包 ${G.inventory.length}／${whCap()}；只收集符合門檻的裝備，其他轉為金幣及零件。滿倉時沿用優先保留稀有度／詞綴階級的規則，受保護物品不會被替換。</p>${rulesBar()}${goldShopHtml()}<p>構築引用及上一件裝備佔用容量；可到構築保管檢視，確認後解除不需要的裝備記憶。核心每款另行收藏，不佔普通背包。</p>`);}
function restoreBattleView(){GAME_VIEW.prefs.hideBattle=false;G.cz=1;G.userCz=false;CUSTOM_H.v=null;AUTO_FOLD.on=false;AUTO_FOLD.t=performance.now();try{localStorage.removeItem('ih-custh')}catch(e){}viewSavePrefs();viewApplyPrefs();uiTitle();uiSyncBattleFrame();uxAnnounce('已回復戰鬥畫面。');}
function lootBattleRestore(){const stage=document.querySelector('.stage');if(!stage)return;let note=document.getElementById('battle-hidden-note');if(!note){note=document.createElement('div');note.id='battle-hidden-note';note.innerHTML='<p>戰鬥畫面已隱藏，戰鬥與收益照常進行；戰鬥音效暫停</p><button type="button" class="mb" onclick="restoreBattleView()">回復顯示</button>';stage.appendChild(note);}note.hidden=!document.body.classList.contains('battle-fold')||(typeof MOB==='function'&&MOB()&&!GAME_VIEW.prefs.hideBattle);}
