/* Shared encounter information and focused device editing. */
const PLAY_UI={owned:true,color:'all'},PLAY_TOUCH=new Map();let PLAY_PINCH=null,PLAY_SUPPRESS=0;
function craftOutcomeHtml(result){
 const before=result.beforeRows||[],after=result.afterRows||[],keys=[...new Set([...before,...after].map(a=>a.k))],rows=keys.map(key=>{const old=before.find(a=>a.k===key),now=after.find(a=>a.k===key);return {key,old,now};}).filter(r=>r.old?.v!==r.now?.v);
 return `<h2>腐化結果</h2><div class="craft-outcome"><strong>${uxEsc(result.msg)}</strong><span>消耗 ${result.cost} 零件 · 已腐化</span></div>${rows.length?`<table class="outcome-table"><caption>實際詞綴變化</caption><thead><tr><th>之前</th><th>之後</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.old?uxEsc(AFF[r.key].t(r.old.v)):'沒有此詞綴'}</td><td>${r.now?uxEsc(AFF[r.key].t(r.now.v)):'已移除'}</td></tr>`).join('')}</tbody></table>`:'<p>詞綴數值沒有變化；這件裝備已獲得腐化狀態，不能再改機。</p>'}<p class="uxmeta">裝備仍在原部位，保留原有鎖定與構築引用。</p><button class="mb" data-initial-focus onclick="hideOverlay()">知道了</button>`;
}
function showCraftOutcome(slot){const r=CRAFT_RESULTS[slot];if(r)showOverlay(craftOutcomeHtml(r));}
function deathSummaryHtml(){const r=G.deathReport;if(!r)return '<p>尚未記錄死亡總結。系統只記錄最近一次線上倒下前8秒的實際承傷。</p>';
 return `<div class="death-cause"><span>最後一擊</span><strong>${uxEsc(r.cause)}</strong><small>${uxEsc(r.area)}</small></div><div class="death-metrics"><div><b>${tFmt(r.total)}</b><span>8秒內承傷（含溢傷）</span></div><div><b>${tFmt(r.shield)}</b><span>護盾吸收</span></div><div><b>${tFmt(r.largest)}</b><span>最大單次承傷</span></div></div><h3>承傷來源</h3>${r.sources.length?`<dl class="death-sources">${r.sources.map(s=>`<div><dt>${uxEsc(s.name)}</dt><dd>${tFmt(s.amount)}</dd><meter min="0" max="${Math.max(1,r.total)}" value="${s.amount}" aria-label="${uxEsc(s.name)}承傷佔比"></meter></div>`).join('')}</dl>`:'<p>沒有足夠來源資料，未推測死因。</p>'}<h3>當時已接通的技能</h3><div class="death-skills">${r.skills.map(id=>`<span>${sico(id,28)}${uxEsc(SKILLS[id].n)}</span>`).join('')||'<p>沒有技能接通。</p>'}</div><p class="uxmeta">承傷是護甲及護盾計算後的命中傷害，包含最後一擊溢傷；沒有記錄走位，不能單憑本表判定哪一個流派較強。</p>`;
}
function showDeathSummary(){showOverlay(`<h2>死亡總結</h2>${deathSummaryHtml()}`);}

function playNewBadge(kind,key){return noticeHas(kind,key)?'<span class="play-new" aria-label="新獲得">NEW</span>':'';}
function playBoardSummary(){const L=GridLab.layout(G.board),res=GridLab.resolve(G.board,G.lvl),wired=res.filter(r=>r.wired).length,power=GridLab.powerUsed(G.board);return `<div class="play-board-readout"><span><b>${wired}／${L.socks.length}</b> 技能接通</span><span><b>${power}／${L.power}</b> 供電</span><button class="mb" onclick="directHelp('skills')" aria-label="接線板操作說明">?</button></div>${!res.length?'<p class="play-empty-hint">第 1 步：點「終」或「起」，選一個技能裝上。</p>':res.some(r=>!r.wired)?`<p class="play-empty-hint" role="status">已裝上 ${uxEsc(res.filter(r=>!r.wired).map(r=>SKILLS[r.key].n).join('、'))}。第 2 步：按住「起」拖到「終」，把線接通。</p>`:G.board.pieces.some(p=>p.kind==='support')?'':'<p class="play-empty-hint" role="status">已接通。第 3 步：點線經過的色塊洞，放入同色配件加強技能。</p>'}${held?`<div class="play-placement" role="status">${held.kind==='support'?gemIco(held.key,28):sico(held.key,28)}<span>${uxEsc((SUPPS[held.key]||SKILLS[held.key]).n)} · ${held.kind==='support'?WIRE_COLNAME[GridLab.GEM_COLOR[held.key]]+'色洞':'技能終點'}</span><button class="mb" onclick="uxCancelPiece();renderModal()">取消放置</button></div>`:''}`;}
function playPortStrip(){const L=GridLab.layout(G.board),res=GridLab.resolve(G.board,G.lvl);return `<div class="play-port-strip" role="group" aria-label="技能接通狀態">${L.socks.map((_,i)=>{const r=res.find(r=>r.sock===i);return `<button class="mb" aria-pressed="${selSock===i}" onclick="playFocusPort(${i})"><span>${i+1} · ${r?SKILLS[r.key].n:'空終點'}</span><small>${r?r.wired?'生效 · '+r.linked.length+'配件':'未接通，不會出手':'點選裝技能'}</small></button>`;}).join('')}</div>`;}
function playFocusPort(i){selSock=i;selPiece=null;renderModal();playFocusBoard();}
function playFocusBoard(){if(!$('ovl').hidden)return;requestAnimationFrame(()=>{document.querySelector('.device-console')?.scrollIntoView({block:'start'});const L=GridLab.layout(G.board),p=L.socks[selSock];if(p)document.querySelector(`.wb .sk[data-x="${p[0]}"][data-y="${p[1]}"]`)?.focus({preventScroll:true});});}
function playInventory(kind){UI_WORK.inventory=kind;renderModal();requestAnimationFrame(()=>document.querySelector('#uxinventory')?.scrollIntoView({block:'start'}));}
function playInventoryFilters(){return `<div class="play-inventory-filters"><button class="mb" aria-pressed="${PLAY_UI.owned}" onclick="PLAY_UI.owned=!PLAY_UI.owned;renderModal()">${PLAY_UI.owned?'持有／已解鎖':'全部目錄'}</button>${UI_WORK.inventory==='support'?`<div role="group" aria-label="配件洞色篩選">${[['all','全部'],['r','紅'],['b','藍'],['g','綠']].map(([id,n])=>`<button class="mb" aria-pressed="${PLAY_UI.color===id}" onclick="PLAY_UI.color='${id}';renderModal()">${n}</button>`).join('')}</div>`:''}</div>`;}
