function playAscensionDescription(n){return `<span class="asc-node-effect">${uxEsc(n.d)}</span>`;}
function talentScaleAt(next,clientX,clientY){
 const v=$('talent-viewport');if(!v)return;const old=TALENT_VIEW.zoom,z=Math.max(.1,Math.min(1.75,next));if(Math.abs(z-old)<.0001)return;const rect=v.getBoundingClientRect(),x=clientX-rect.left,y=clientY-rect.top,worldX=(v.scrollLeft+x)/old,worldY=(v.scrollTop+y)/old;TALENT_VIEW.zoom=z;TALENT_VIEW.fit=false;const plane=v.querySelector('.talent-plane');plane.style.width=2240*z+'px';plane.style.height=2240*z+'px';v.classList.toggle('overview',z<.75);for(const node of v.querySelectorAll('[data-talent]')){const n=TREE[node.dataset.talent],p=talentPosition(n);node.style.left=p.x*z+'px';node.style.top=p.y*z+'px';node.style.setProperty('--overview-size',Math.max(7,Math.min(24,(n.big?38:24)*z))+'px');}v.scrollLeft=worldX*z-x;v.scrollTop=worldY*z-y;TALENT_VIEW.left=v.scrollLeft;TALENT_VIEW.top=v.scrollTop;const readout=$('talent-zoom-readout');if(readout)readout.textContent=Math.round(z*100)+'%';const out=document.querySelector('[data-talent-zoom="out"]'),into=document.querySelector('[data-talent-zoom="in"]');if(out)out.disabled=z<=.1;if(into)into.disabled=z>=1.75;
}
function talentWheel(e){e.preventDefault();talentScaleAt(TALENT_VIEW.zoom*Math.exp(-e.deltaY*.0015),e.clientX,e.clientY);}
function talentPageScroller(v){for(let n=v.parentElement;n;n=n.parentElement){const o=getComputedStyle(n).overflowY;if(/(auto|scroll)/.test(o)&&n.scrollHeight>n.clientHeight+1)return n;}return document.scrollingElement;}
function talentTouchStart(e){const v=e.currentTarget;PLAY_TOUCH.set(e.pointerId,{x:e.clientX,y:e.clientY});if(PLAY_TOUCH.size===1)TALENT_VIEW.gesture={id:e.pointerId,x:e.clientX,y:e.clientY,page:true,sy:e.clientY,sc:talentPageScroller(v)};if(PLAY_TOUCH.size===2){TALENT_VIEW.gesture=null;const[a,b]=[...PLAY_TOUCH.values()];PLAY_PINCH={distance:Math.hypot(a.x-b.x,a.y-b.y),zoom:TALENT_VIEW.zoom,cx:(a.x+b.x)/2,cy:(a.y+b.y)/2};PLAY_SUPPRESS=performance.now()+400;for(const id of PLAY_TOUCH.keys())try{v.setPointerCapture(id);}catch(_){}}}
function talentTouchMove(e){if(!PLAY_TOUCH.has(e.pointerId))return;PLAY_TOUCH.set(e.pointerId,{x:e.clientX,y:e.clientY});const v=e.currentTarget;if(PLAY_TOUCH.size>=2&&PLAY_PINCH){e.preventDefault();const[a,b]=[...PLAY_TOUCH.values()],cx=(a.x+b.x)/2,cy=(a.y+b.y)/2;v.scrollLeft-=cx-PLAY_PINCH.cx;v.scrollTop-=cy-PLAY_PINCH.cy;PLAY_PINCH.cx=cx;PLAY_PINCH.cy=cy;talentScaleAt(PLAY_PINCH.zoom*Math.hypot(a.x-b.x,a.y-b.y)/Math.max(1,PLAY_PINCH.distance),cx,cy);PLAY_SUPPRESS=performance.now()+400;}else{const d=TALENT_VIEW.gesture;if(d?.page){const dy=d.y-e.clientY;if(Math.abs(dy)>0){d.sc.scrollTop+=dy;d.y=e.clientY;if(Math.abs(e.clientY-d.sy)>8)PLAY_SUPPRESS=performance.now()+400;}}}}
function talentTouchEnd(e){PLAY_TOUCH.delete(e.pointerId);if(PLAY_PINCH){PLAY_PINCH=null;PLAY_SUPPRESS=performance.now()+400;}TALENT_VIEW.gesture=null;uiTreeRemember();}
