function storyPixelMarkup(step,svg){const alt=['午後街區的電台訊號','錄音卡匣','通往高架橋的訊號路線'][step],markup=url=>`<img class="intro-radio pixel-story" data-story-scene="${step}" width="160" height="80" alt="${alt}" src="${url}">`;if(STORY_RASTER[step])return markup(STORY_RASTER[step]);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=160;canvas.height=80;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.drawImage(img,0,0,160,80);const url=STORY_RASTER[step]=canvas.toDataURL('image/png'),node=document.querySelector(`.intro-radio[data-story-scene="${step}"]`);if(node){const template=document.createElement('template');template.innerHTML=markup(url);node.replaceWith(template.content.firstElementChild);}};img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg.replace('<svg ','<svg xmlns="http://www.w3.org/2000/svg" '));return svg.replace('<svg ','<svg style="shape-rendering:crispEdges" ');}
