const FEEDBACK_STATE={busy:false,requestId:null,message:'',sent:null};
function feedbackHtml(){const d=FEEDBACK_DRAFT,configured=!!FEEDBACK_CONFIG.endpoint;return `<form class="ui-feedback" novalidate onsubmit="event.preventDefault();feedbackPreview()"><p>回報錯誤、平衡問題或玩法建議，直接在這裡送出。</p><p class="feedback-delivery">${configured?'回饋會公開，請勿填寫個人資料、密碼或存檔碼。':'回饋服務尚未接通；你可以先保留或下載草稿，目前不會送出。'}</p>${FEEDBACK_STATE.sent?`<p role="status">已收到回饋，單號 ${FEEDBACK_STATE.sent}。</p>`:''}<fieldset ${FEEDBACK_STATE.busy?'disabled':''}><legend class="uxsr">回饋內容</legend><label for="feedback-category">類別<select id="feedback-category" onchange="FEEDBACK_DRAFT.category=this.value;FEEDBACK_STATE.requestId=null">${['錯誤','平衡','玩法建議','其他'].map(n=>`<option ${d.category===n?'selected':''}>${n}</option>`).join('')}</select></label><label for="feedback-title">標題（最多60字）<input id="feedback-title" maxlength="60" value="${uxEsc(d.title)}" aria-describedby="feedback-error" oninput="FEEDBACK_DRAFT.title=this.value;feedbackClearError(this)"></label><label for="feedback-details">內容（最多700字）<textarea id="feedback-details" maxlength="700" aria-describedby="feedback-error" oninput="FEEDBACK_DRAFT.details=this.value;feedbackClearError(this)">${uxEsc(d.details)}</textarea></label><label class="ui-feedback-consent"><input type="checkbox" ${d.device?'checked':''} onchange="FEEDBACK_DRAFT.device=this.checked;FEEDBACK_STATE.requestId=null">附上瀏覽器與畫面尺寸（可選）</label></fieldset><p class="uxmeta">只附版本號；不附角色名稱、進度或存檔。</p><p id="feedback-error" class="ui-feedback-error" role="alert">${uxEsc(FEEDBACK_STATE.message)}</p><div class="uxactions"><button class="mb pri" type="submit" ${!configured||FEEDBACK_STATE.busy?'disabled':''} aria-busy="${FEEDBACK_STATE.busy}">${FEEDBACK_STATE.busy?'正在送出…':'公開送出回饋'}</button><button class="mb" type="button" ${FEEDBACK_STATE.busy?'disabled':''} onclick="feedbackDownload()">下載草稿</button></div></form>`;}
async function feedbackPreview(){
 if(FEEDBACK_STATE.busy)return;const draft={...FEEDBACK_DRAFT},payload=feedbackPayload(draft);if(!payload){const field=!draft.title.trim()||draft.title.length>60?$('feedback-title'):$('feedback-details');$('feedback-error').textContent='請填寫標題及內容，並遵守字數上限。';field.setAttribute('aria-invalid','true');field.focus();return;}if(!FEEDBACK_CONFIG.endpoint){FEEDBACK_STATE.message='服務尚未接通，草稿仍保留。';renderModal();return;}
 FEEDBACK_STATE.requestId=FEEDBACK_STATE.requestId||crypto.randomUUID();const requestId=FEEDBACK_STATE.requestId;FEEDBACK_STATE.busy=true;FEEDBACK_STATE.sent=null;FEEDBACK_STATE.message='';renderModal();const control=new AbortController(),timer=setTimeout(()=>control.abort(),15000);
 try{const response=await fetch(FEEDBACK_CONFIG.endpoint,{method:'POST',headers:{'content-type':'application/json'},credentials:'omit',signal:control.signal,body:JSON.stringify({requestId,category:draft.category,title:draft.title,details:draft.details,version:VERSION(),device:draft.device?navigator.userAgent.slice(0,180)+'；'+innerWidth+' × '+innerHeight:''})});const result=await response.json();if(response.status===202){FEEDBACK_STATE.message='送出狀態尚未確認，請稍後使用同一草稿重試；目前不會重複派送。';}else if(!response.ok||!result.ok||!Number.isSafeInteger(result.receipt)){throw Error('delivery');}else{FEEDBACK_STATE.sent=result.receipt;FEEDBACK_DRAFT.title='';FEEDBACK_DRAFT.details='';FEEDBACK_STATE.requestId=null;}}
 catch(e){FEEDBACK_STATE.message='未能確認送出，草稿已保留。請稍後重試或先下載草稿。';}
 finally{clearTimeout(timer);FEEDBACK_STATE.busy=false;if(modalTab==='feedback'){renderModal();$('feedback-title')?.focus({preventScroll:true});}}
}

