const STUDIO_UI={pact:'steady',drawer:null};
// Set only to Alan's confirmed public Patreon creator page; never infer an account.
const SUPPORT_CONFIG={url:'https://www.patreon.com/c/alanycchan'};

function studioMachine(id){return deviceThumb('studio-machine:'+id,()=>{const g=new T3.Group(),silver=m3('#bccbd8'),ink=m3('#2c4160'),signal=m3({core:'#b3a4d3',rules:'#8db7ef',shop:'#d6ba7b',synth:'#80cebd'}[id]);mk(roundedG(3,1,2.5),ink,0,0,0,g);if(id==='core'){mk(new T3.CylinderGeometry(.9,1,1.8,8),silver,0,1.1,0,g);mk(new T3.OctahedronGeometry(.55,0),signal,0,2.6,0,g);for(const x of[-1.2,1.2])mk(roundedG(.3,2,.3),signal,x,1,0,g);}if(id==='rules'){for(const[x,y]of[[-.7,.8],[0,1.3],[.7,1.8]]){mk(new T3.CylinderGeometry(.3,.3,.4,8),signal,x,y,0,g);mk(roundedG(.15,y,.15),silver,x,y/2,0,g);}}if(id==='shop'){mk(roundedG(2.2,2.8,1.6),silver,0,1.5,0,g);mk(roundedG(1.6,1.1,.12),ink,0,1.8,.85,g);mk(new T3.CylinderGeometry(.55,.55,.18,10),signal,0,.8,.95,g).rotation.x=Math.PI/2;}if(id==='synth'){mk(new T3.TorusGeometry(1,.2,4,10),silver,0,1.5,0,g);for(const x of[-.55,.55])mk(new T3.OctahedronGeometry(.4,0),signal,x,1.5,.1,g);}g.rotation.set(.2,-.35,0);return g;});}
function studioDrawer(id){STUDIO_UI.drawer=STUDIO_UI.drawer===id?null:id;renderModal();requestAnimationFrame(()=>document.getElementById('studio-drawer')?.scrollIntoView({block:'nearest'}));}
function studioUnwrap(html){return html.replace(/^<details[^>]*>/,'').replace(/<summary>[\s\S]*?<\/summary>/,'').replace(/<\/details>$/,'')}
function studioUtilitiesHtml(){const slot=UI_WORK.craftSlot,it=G.equip[slot],items=[['core','核心重構',G.coreDust+' 殘晶'],['rules','拾取規則',G.inventory.length+'／'+whCap()],['shop','補給站',tFmt(G.gold)+' 金幣'],['synth','電路合成',tFmt(G.chips)+' 點']];let content='';if(STUDIO_UI.drawer==='core')content=it?.lg?coreRefineHtml(slot,it).replace('<details','<details open'):'<p>選中穿著中的傳奇裝備，再用殘晶提高物品等級。</p><button class="mb" onclick="openModal(\'warehouse\')">查看背包</button>';if(STUDIO_UI.drawer==='rules')content=rulesBar()+'<p class="device-caption">回收低於門檻的掉落；穿著、鎖定、腐化及構築引用保持原有保護。</p><button class="mb" onclick="lootCleanupOpen()">篩選分解</button>';if(STUDIO_UI.drawer==='shop')content=goldShopHtml().replace('<details','<details open');if(STUDIO_UI.drawer==='synth')content=circuitShopHtml().replace('<details','<details open');return `<section class="studio-utilities" aria-label="整備設備">${items.map(([id,n,v])=>`<button class="mb studio-machine" aria-expanded="${STUDIO_UI.drawer===id}" aria-controls="studio-drawer" onclick="studioDrawer('${id}')"><img alt="" width="64" height="64" src="${studioMachine(id)}"><span><b>${n}</b><small>${v}</small></span></button>`).join('')}</section>${STUDIO_UI.drawer?`<section id="studio-drawer" class="studio-drawer"><div class="studio-drawer-title"><h3>${items.find(x=>x[0]===STUDIO_UI.drawer)[1]}</h3><button class="mb" aria-label="收起設備詳情" onclick="studioDrawer('${STUDIO_UI.drawer}')">−</button></div>${studioUnwrap(content)}</section>`:''}`;}
function towerDiagram(floor,best){const base=Math.floor((Math.max(1,floor)-1)/10)*10;return `<div class="tower-spine" role="img" aria-label="第${floor}層，最高完成${best}層">${Array.from({length:10},(_,i)=>base+10-i).map(n=>`<div class="tower-storey ${n===floor?'current':n<=best?'cleared':''}"><span>${n===floor?'▶':''}</span><b>${n}</b><i>${n%10===0?'✦':'▰'}</i></div>`).join('')}</div>`;}
function towerConsoleHtml(){const R=G.run?.tower?G.run:null,floor=R?.floor||1,best=G.towerBest||0,next=Math.ceil(floor/10)*10,cur=R?Math.min(R.kills,R.need):0,pct=R?Math.round(cur/R.need*100):0;return `<section class="tower-console tower-v2"><header><span>無限之塔</span><b>上行電波</b></header>${liveTowerHtml(floor)}<div class="tower-hero"><div class="tower-big"><span>${R?'目前樓層':'最高完成'}</span><strong>${R?floor:best}<small> F</small></strong></div>${R?`<div class="tower-prog" role="status"><div class="tower-bar"><i style="width:${pct}%"></i></div><small>${R.stair?'正在沿樓梯上行…':'本層討伐 '+cur+'／'+R.need}</small></div>`:`<p class="tower-tip">每十層一隻BOSS，通關後增加一條干擾規則。</p>`}</div><div class="tower-stats"><div><span>下個BOSS</span><b>${next} F</b></div><div><span>本層零件</span><b>＋${3+Math.floor(floor/5)}</b></div><button class="mb tower-shard" onclick="lootSources()"><span>階層鎖片</span><b>${activityLoot().tower}／3</b></button></div><div class="tower-console-actions"><button class="mb pri" ${G.run||G.train||G.maxDepth<8?'disabled':''} onclick="towerStart()">${G.maxDepth<8?'深度8解鎖':'開始攀升'}</button>${R?.stair?'<button class="mb" onclick="towerSkipStair()">略過上行動畫</button>':''}${R?'<button class="mb" onclick="uiLeaveMap()">離開塔樓</button>':''}<button class="mb" onclick="towerHelp()">規則</button></div></section>`;}
function towerSkipStair(){if(G.run?.stair)towerStairTick(0,true);renderModal()}
function towerHelp(){showOverlay('<h2>無限之塔</h2><p>每層討伐指定敵人，再沿樓梯上行。每十層出現BOSS；完成BOSS層會增加干擾與獎勵。</p><p>每層結算金幣、零件，回復30%生命並清除異常。倒下結束攀升，已結算獎勵保留。上行動畫可略過，獎勵不重複。</p>')}
function seasonLaunch(route,finale=false){if(!seasonStart(route,STUDIO_UI.pact,finale)){uxAnnounce('目前不能出發，請確認解鎖、頻段充能及目前挑戰。');return;}renderModal();uxAnnounce(finale?'已消耗三頻充能，午夜中樞開始。':'巡迴委託開始。');}
function seasonRedeem(id,cycle){if(!seasonClaim(id,cycle)){uxAnnounce('尚未達成，或獎勵已領取。');return;}const saved=saveGame();renderModal();uxAnnounce(saved?'巡迴獎勵已領取。':'已領取但未能保存，請匯出備份後重試保存。');}
function seasonHtml(){const s=seasonEnsure(),end=SEASON_EPOCH+(s.cycle+1)*SEASON_DAYS*864e5,days=Math.max(0,Math.ceil((end-Date.now())/864e5)),ready=cityReady()&&!G.run&&!G.train,charged=Object.values(s.charge).every(n=>n>0);return `<section class="season-console"><header><span>第${s.cycle+1}期 · 尚餘${days}天</span><h3>斷訊電台</h3><span class="season-token-count">頻段結晶 ${activityLoot().season}</span><p>回收三段頻率，向午夜中樞播送。</p></header><div class="season-pacts" role="group" aria-label="巡迴風險">${Object.entries(SEASON_PACTS).map(([id,p])=>`<button class="mb" aria-pressed="${STUDIO_UI.pact===id}" onclick="STUDIO_UI.pact='${id}';renderModal()">${p.n}</button>`).join('')}</div><p class="device-caption">${SEASON_PACTS[STUDIO_UI.pact].d}</p><div class="season-frequencies">${Object.entries(SEASON_ROUTES).map(([id,r],i)=>`<article style="--freq:${r.col}"><div class="frequency-dial" aria-hidden="true"><img src="${studioMachine(['rules','core','synth'][i])}" alt="" width="44" height="44"></div><div><h4>${r.n}</h4><span>${r.tag} · 完成 ${s.clears[id]} 次</span><div class="frequency-charge" role="img" aria-label="${s.charge[id]}／6充能">${Array.from({length:6},(_,n)=>`<i class="${n<s.charge[id]?'on':''}"></i>`).join('')}</div></div><button class="mb" ${ready?'':'disabled'} onclick="seasonLaunch('${id}')">出發</button></article>`).join('')}</div><section class="midnight-core"><span>終局播送</span><h4>午夜中樞</h4><p>三頻各消耗1格；三段戰鬥、加速干擾與階段脈衝。失敗不退充能。</p><button class="mb pri" ${ready&&charged?'':'disabled'} onclick="seasonFinaleAsk()">${charged?'開啟午夜中樞':'收集三頻充能'}</button><span>完成紀錄 ${s.wins}</span></section><div class="season-milestones">${SEASON_MILESTONES.map(m=>`<div><span class="season-stamp ${seasonMilestoneReady(m.id)?'ready':''}">${s.claimed.includes(m.id)?'✓':'◇'}</span><span><b>${m.n}</b><small>${m.d} · ${m.parts}零件／${m.chips}點</small></span><button class="mb" ${seasonMilestoneReady(m.id)&&!s.claimed.includes(m.id)?'':'disabled'} onclick="seasonRedeem('${m.id}',${s.cycle})">${s.claimed.includes(m.id)?'已領':'領取'}</button></div>`).join('')}</div><p class="device-caption">28天個人巡迴，保存於本機；換季只更新巡迴紀錄，保留角色與裝備。深度8解鎖，沿用城市三段路線與分支。</p>${s.history.length?`<details><summary>歷期紀錄</summary>${s.history.map(h=>`<p>第${h.cycle+1}期 · 委託${h.clears}次／中樞${h.wins}次</p>`).join('')}</details>`:''}</section>`;}
function seasonFinaleAsk(){const cycle=seasonEnsure().cycle;showOverlay('<h2>開啟午夜中樞？</h2><p>消耗三頻各1格充能。倒下或離開不退還；完成三段挑戰後獲得25零件，並更新本期紀錄。</p><div class="uxactions"><button class="mb" data-initial-focus onclick="hideOverlay()">取消</button><button class="mb pri" onclick="seasonFinaleConfirm('+cycle+')">消耗充能並出發</button></div>')}
function seasonFinaleConfirm(cycle){hideOverlay();if(seasonEnsure().cycle!==cycle)return uxAnnounce('巡迴已換期，請重新確認。');seasonLaunch('signal',true)}
function supportDestination(value=SUPPORT_CONFIG.url){
  if(typeof value!=='string'||!value.trim())return '';
  try{
    const u=new URL(value.trim());
    if(u.protocol!=='https:'||!['patreon.com','www.patreon.com'].includes(u.hostname)||u.port||u.username||u.password||u.hash)return '';
    // Public creator routes only. Membership/checkout and authentication stay on Patreon.
    const path=u.pathname.replace(/\/$/,'');
    const reserved=/^(?:login|logout|signup|join|checkout|settings|account|home|explore|search|create|pricing|policy|legal|oauth2|user|c)$/i;
    const creator=/^\/c\/[A-Za-z0-9_-]+$/.test(path)||(/^\/[A-Za-z0-9_-]+$/.test(path)&&!reserved.test(path.slice(1)));
    const legacy=path==='/user'&&/^\?u=[1-9][0-9]*$/.test(u.search);
    if(!legacy&&(!creator||u.search))return '';
    return 'https://www.patreon.com'+path+(legacy?u.search:'');
  }catch{return '';}
}
function supportHtml(){
  const destination=supportDestination();
  return `<section class="support-console" aria-labelledby="support-heading">
    <header class="support-hero"><div class="support-disc" aria-hidden="true">♡</div><p class="support-kicker">IDLE HERO</p><h3 id="support-heading">支持開發</h3></header>
    <div class="support-letter"><p>Idle Hero 是我的個人興趣作品。謝謝你遊玩，歡迎透過 Patreon 支持開發。</p></div>
    <div class="support-channel">
      ${destination?`<a class="mb support-cta" href="${uxEsc(destination)}" target="_blank" rel="noopener noreferrer">前往 Patreon ↗<span class="uxsr">（另開分頁）</span></a>`:'<button class="mb support-cta" type="button" disabled aria-describedby="support-unavailable">Patreon 贊助尚未開放</button><p id="support-unavailable" class="support-unavailable">Patreon 頁面準備中。</p>'}
      <p class="support-note">自願支持，不影響遊戲內容與進度。</p>
    </div>
    <footer class="support-footer"><div class="uxactions"><button class="mb" data-focus="support-feedback" onclick="openModal('feedback')">留下意見</button><button class="mb" data-focus="support-credits" onclick="audioCredits()">聲音鳴謝</button></div></footer>
  </section>`;
}
function audioCredits(){showOverlay('<h2>聲音鳴謝</h2><p>Dream Static：symphony。Dream（Ambience）：TokyoGeisha。Retro Game Music Pack：Juhani Junkala。Interface Sounds：Kenney。</p><p>均採CC0授權，經片段編輯、濾波與音量整理。完整來源及衍生紀錄隨遊戲原始碼保存。</p><button class="mb" onclick="audUnlock()">啟用聲音</button>')}
let STUDIO_TIP=null,STUDIO_TIP_TARGET=null,STUDIO_TIP_TIMER=null,STUDIO_LAST_TOUCH=-9999;
function studioTipHide(){clearTimeout(STUDIO_TIP_TIMER);STUDIO_TIP?.remove();if(STUDIO_TIP_TARGET)STUDIO_TIP_TARGET.removeAttribute('aria-describedby');STUDIO_TIP=null;STUDIO_TIP_TARGET=null;}
function studioTalentTip(button){studioTipHide();const id=button.dataset.talent,n=TREE[id];if(!n)return;STUDIO_TIP_TARGET=button;const tip=STUDIO_TIP=document.createElement('div');tip.id='studio-talent-tip';tip.role='tooltip';tip.className='studio-tooltip';tip.innerHTML=`<b>${uxEsc(id==='S'?'起點':talentName(id))}</b><p>${uxEsc(id==='S'?'從相連支線開始構築。':FIRMWARE[id]?.d||effText(n.eff))}</p><small>${G.pass.includes(id)?'已投入':canAllocateTalent(id)?'可投入1點':'先連接前置節點'}</small>`;document.body.append(tip);button.setAttribute('aria-describedby',tip.id);const r=button.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+'px';tip.style.top=(r.top-h-8>8?r.top-h-8:Math.min(innerHeight-h-8,r.bottom+8))+'px';}
function studioQueueTip(button){clearTimeout(STUDIO_TIP_TIMER);STUDIO_TIP_TIMER=setTimeout(()=>{if(button.isConnected&&(button.matches(':hover')||document.activeElement===button))studioTalentTip(button)},120)}
document.addEventListener('pointerover',e=>{if(e.pointerType==='touch')return;const b=e.target.closest?.('[data-talent]');if(b)studioQueueTip(b)});document.addEventListener('pointerout',e=>{if(e.target.closest?.('[data-talent]')&&!e.relatedTarget?.closest?.('[data-talent]'))studioTipHide()});document.addEventListener('focusin',e=>{const b=e.target.closest?.('[data-talent]');if(b&&performance.now()-STUDIO_LAST_TOUCH>500)studioQueueTip(b);else studioTipHide()});document.addEventListener('scroll',()=>{if(STUDIO_TIP){const b=STUDIO_TIP_TARGET;studioTipHide();if(b?.isConnected)studioQueueTip(b)}},true);document.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')STUDIO_LAST_TOUCH=performance.now();studioTipHide()},true);document.addEventListener('keydown',e=>{STUDIO_LAST_TOUCH=-9999;if(e.key==='Escape')studioTipHide()},true);
