function stageSignals(){const stage=document.querySelector('.stage');if(!stage)return;let panel=document.getElementById('stage-signals');if(!panel){panel=document.createElement('div');panel.id='stage-signals';panel.innerHTML='<section id="boss-signal" hidden><strong></strong><span></span><progress max="1" aria-label="BOSS生命"></progress></section><section id="tower-ascent" hidden><b></b><progress max="1" aria-label="登階進度"></progress><button class="mb" onclick="towerStairTick(0,true)">略過</button></section>';stage.appendChild(panel)}const hidden=document.body.classList.contains('battle-fold')||document.body.classList.contains('battle-off'),boss=G.mons.find(m=>m.boss&&!m.dead),box=panel.querySelector('#boss-signal');box.hidden=hidden||!boss;if(boss&&!hidden){if(!STAGE_UI.seen.has(boss)){STAGE_UI.seen.add(boss);STAGE_UI.warningUntil=performance.now()+2300;}const intro=performance.now()<STAGE_UI.warningUntil;box.classList.toggle('entering',intro);box.querySelector('strong').textContent=intro?'WARNING · BOSS接近':(boss.enraged?'BOSS · 覺醒':'BOSS戰鬥');box.querySelector('span').textContent=({warden:'總掣值班長',chimera:'回帶港務機',executor:'分揀塔監督'}[boss.towerBoss]||(boss.chap!=null&&STORY_CHAPTERS[boss.chap]?.boss)||['總掣工頭','回帶港務機','無主分揀塔'][boss.bossForm||0]);box.querySelector('progress').value=Math.max(0,boss.hp/boss.hpMax);}let rb=panel.querySelector('#rift-signal');if(!rb){rb=document.createElement('section');rb.id='rift-signal';panel.appendChild(rb)}const re=riftState().encounter;rb.hidden=hidden||!re;if(re){rb.innerHTML=`<b>${{dormant:'斷訊手',expand:'裂隙擴張',contain:'收束裂隙',complete:'封閉完成',failed:'訊號逸散'}[re.phase]}</b><span>${re.phase==='dormant'?'接近啟動':re.kills+'／22 · '+Math.max(0,Math.ceil(55-re.age))+'秒'}</span>`;}const a=G.run?.stair,climb=panel.querySelector('#tower-ascent');climb.hidden=hidden||!a;if(a){climb.querySelector('b').textContent=a.from+' F → '+(a.from+1)+' F · 登階';climb.querySelector('progress').value=a.age/(a.duration||1);}let loot=document.getElementById('loot-receipts');if(!loot){loot=document.createElement('div');loot.id='loot-receipts';loot.setAttribute('role','log');loot.setAttribute('aria-label','最近獲得');stage.append(loot)}for(const[key,r]of STAGE_UI.receipts)if(r.until<performance.now())STAGE_UI.receipts.delete(key);loot.hidden=hidden;const html=[...STAGE_UI.receipts.values()].map(r=>`<div style="--rc:${RAR[r.r]?.c||'#80cebd'}">${uxEsc(r.text)}</div>`).join('');if(loot.innerHTML!==html)loot.innerHTML=html;}
function skillBlueprintBuy(id){const k=SKILLS[id];if(!k||G.skillBooks?.[id])return;if(G.chips<skillBlueprintCost(id)){showOverlay('<h2>電路點數不足</h2><p>需要'+skillBlueprintCost(id)+'點，目前持有'+G.chips+'點。圖紙亦可由符合等級的魔物與BOSS掉落。</p>');return;}showOverlay(`<h2>兌換${uxEsc(k.n)}？</h2><p>${skillFindLabel(id)} · ${skillBlueprintCost(id)}電路點數</p><p>${uxEsc(k.d)}</p><button class="mb" data-initial-focus onclick="hideOverlay()">取消</button><button class="mb pri" onclick="if(buySkillBlueprint('${id}')){hideOverlay();renderModal()}else{uxAnnounce('資源不足或已取得，沒有扣款。')}">確認兌換</button>`);}
function skillBlueprintShelf(){const ids=Object.keys(SKILLS).filter(id=>!skillAvailable(id)&&G.lvl>=SKILLS[id].lvl);return ids.length?`<details class="ui-section"><summary>技能圖紙 · BOSS保底 ${G.skillPity||0}／4</summary><p class="uxmeta">四次符合等級的BOSS掉落機會內保底一張未擁有圖紙（仍有未持有時）。一般魔物也會掉落；重複圖紙轉8電路。可直接定向兌換。</p><div class="blueprint-grid">${ids.map(id=>`<button class="mb" ${G.chips<skillBlueprintCost(id)?'disabled':''} onclick="skillBlueprintBuy('${id}')">${sico(id,32)}<span>${SKILLS[id].n}<small>${skillFindLabel(id)} · ${skillBlueprintCost(id)}電路</small></span></button>`).join('')}</div></details>`:'';}
