/* Shared experience controls. Gameplay rewards stay in 02g-rift and existing owners. */
const WIRE_HISTORY={owner:'',rows:[],index:-1};
function wireHistoryObserve(){if(!G.board)return;const owner=(typeof PROFILE_SESSION==='undefined'?'':PROFILE_SESSION.active)+':'+G.board.template+':'+JSON.stringify([G.gems,G.gemTier]),json=JSON.stringify(G.board);if(owner!==WIRE_HISTORY.owner){WIRE_HISTORY.owner=owner;WIRE_HISTORY.rows=[json];WIRE_HISTORY.index=0;return}if(WIRE_HISTORY.rows[WIRE_HISTORY.index]===json)return;WIRE_HISTORY.rows.splice(WIRE_HISTORY.index+1);WIRE_HISTORY.rows.push(json);if(WIRE_HISTORY.rows.length>40)WIRE_HISTORY.rows.shift();WIRE_HISTORY.index=WIRE_HISTORY.rows.length-1;}
function wireHistoryStep(dir){wireHistoryObserve();const next=WIRE_HISTORY.index+dir;if(next<0||next>=WIRE_HISTORY.rows.length)return;WIRE_HISTORY.index=next;G.board=JSON.parse(WIRE_HISTORY.rows[next]);held=null;selPiece=null;selSock=-1;recalc();renderModal();uxAnnounce(dir<0?'已回到上一步。':'已前進一步。');}
function importantLoot(d){return d.kind==='item'?d.it.r===3:d.kind==='skill'||d.kind==='circuit'||d.kind==='rift'||d.kind==='activity'||d.kind==='boost'||d.kind==='gem'&&G.gems[d.id]===1;}
function phoneZoomBy(factor){PH.zoomScale=Math.max(.7,Math.min(2.8,(PH.zoomScale||1)*factor));phoneFit();}
function phoneGestureMount(root){const points=new Map();let distance=0;root.addEventListener('wheel',e=>{e.preventDefault();phoneZoomBy(Math.exp(-e.deltaY*.0015))},{passive:false});root.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch')return;points.set(e.pointerId,[e.clientX,e.clientY]);if(points.size===2){PH.drag=null;const p=[...points.values()];distance=Math.hypot(p[1][0]-p[0][0],p[1][1]-p[0][1]);for(const id of points.keys())root.setPointerCapture?.(id);e.stopImmediatePropagation();}},true);root.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,[e.clientX,e.clientY]);if(points.size!==2)return;const p=[...points.values()],d=Math.hypot(p[1][0]-p[0][0],p[1][1]-p[0][1]);if(distance>8&&d>8)phoneZoomBy(d/distance);distance=d;PH.drag=null;e.preventDefault();e.stopImmediatePropagation()},true);const up=e=>{points.delete(e.pointerId);distance=0;if(points.size)PH.drag=null;};root.addEventListener('pointerup',up,true);root.addEventListener('pointercancel',up,true);}
function riftStatusLabel(e){return ({dormant:'自動前往接觸斷訊手',expand:'訊號擴張',contain:'壓制並封閉',complete:'封閉完成',failed:'訊號逸散'}[e.phase]||'斷訊')+' · '+e.kills+'／22'+(['expand','contain'].includes(e.phase)?' · '+Math.max(0,Math.ceil(55-e.age))+'秒':'');}
function riftPanelHtml(){const s=riftState(),e=s.encounter;return `<section class="rift-console"><header><h3>斷訊裂隙</h3><span>斷訊碎片 ${s.shards} · 封閉 ${s.clears}</span></header><p>深度4後，普通冒險有機會出現斷訊手。接近啟動，擴張18秒後收束；55秒內討伐22隻裂隙魔物即可封閉。途中倒下或離開區域，未完成進度中止。</p>${e?`<div class="rift-status"><span data-rift-status>${riftStatusLabel(e)}</span></div>`:'<p class="uxmeta">在普通區域持續戰鬥，尋找下一次訊號干擾。</p>'}<div class="rift-forge">${['W_RIFT','R_RIFT'].map(id=>`<article>${xico('legend',id,48)}<h4>${LEGEND_BY[id].name}</h4><p>${LEGEND_BY[id].d}</p><button class="mb" ${s.shards<40||G.armory[id]?'disabled':''} onclick="riftForgeAsk('${id}')">${G.armory[id]?'已收藏':'鍛造 · 40碎片'}</button></article>`).join('')}</div><button class="mb" onclick="lootSources()">戰利品來源</button></section>`;}
function riftForgeAsk(id){if(!['W_RIFT','R_RIFT'].includes(id))return;showOverlay(`<h2>鍛造${LEGEND_BY[id].name}？</h2><p>消耗40斷訊碎片，收進背包，不自動裝備。</p><button class="mb" data-initial-focus onclick="hideOverlay()">取消</button><button class="mb pri" onclick="if(riftForge('${id}')){hideOverlay();renderModal()}else uxAnnounce('碎片不足或背包已滿，未扣碎片。')">確認鍛造</button>`);}
function lootSources(){showOverlay(`<h2>戰利品來源</h2><div class="source-grid"><article><h3>普通冒險</h3><p>裝備、寶石、技能圖紙、地圖。角色專屬裝備可由所有怪物極低機率掉落：普通0.001%、精英0.01%、BOSS0.1%。需拾取；只有對應職業能穿。</p></article><article><h3>城市遠征</h3><p>三條路線的城市碎片與殘晶，用於定向追求既有傳奇核心。</p></article><article><h3>無限之塔</h3><p>每完成十層獲得1階層鎖片，累積3片鍛造階層屏障；樓層另結算金錢、零件及干擾。</p></article><article><h3>賽季巡迴</h3><p>三頻專屬充能；消耗充能挑戰午夜中樞，達成當期里程碑；午夜中樞每次勝利獲得1頻段結晶，3枚可鍛造午夜廣播器。</p></article><article><h3>斷訊裂隙</h3><p>專屬斷訊碎片，只能鍛造遠域斷訊器及閉環殘響。</p></article></div>${activityRecipesHtml()}<h3>構築核心</h3>${['W_ECHO','W_FORK','R_LAST','R_LINK','W_RIFT','R_RIFT'].map(id=>`<p><b>${LEGEND_BY[id].name}</b>：${LEGEND_BY[id].d}</p>`).join('')}<p class="uxmeta">DPS為單體直接傷害預估；持續傷害、部分觸發及召喚收益不完整計入，請配合訓練場實測。</p>`);}
