/* Focused first-session UI and a single seasonal workspace. No parallel reward owner. */
function onboardingResume(){onboardingStart(false);hideOverlay();openModal('char');onboardingMount();saveGame();}
function onboardingGo(){const t=G.tutorial;if(!t)return;if(t.stage===1){if(modalTab!=='warehouse'){openModal('warehouse');return;}const it=G.inventory.find(it=>G.equip[it.slot]!==it);if(it)uiInspectGear(it.uid);else uxAnnounce('裝備仍在地上，角色會走近拾取。');}else if(t.stage===2){if(modalTab!=='skills'){UI_WORK.inventory='active';openModal('skills');}else{const L=GridLab.layout(G.board),i=L.socks.findIndex((_,i)=>wOpen(i));if(i>=0){wirePickSock(i,true);document.querySelector('.wb .src')?.scrollIntoView({block:'nearest'});}}}else if(t.stage===3){onboardingFinish();renderModal();}}
function onboardingCopy(){const t=G.tutorial;if(!t)return null;if(t.stage===0)return{n:1,title:'戰鬥會自動進行',text:'角色會自行攻擊、走近拾取。先觀察3次討伐，再試一次配裝。',progress:Math.min(3,Math.max(0,G.totalKills-t.startKills))+'／3',action:''};if(t.stage===1)return{n:2,title:'比較，再換上裝備',text:G.inventory.some(it=>G.equip[it.slot]!==it)?'點一件未穿裝備，查看數值比較，再按「換上」。':'裝備落地後，角色會自動走近拾取；拾取後再打開背包。',progress:'手動配裝',action:modalTab==='warehouse'?'比較裝備':'打開背包'};if(t.stage===2){const active=G.board.pieces.some(p=>p.kind==='active');return{n:3,title:'接通第一個技能',text:active?'按住「起」，沿空格拖到同色「終」；亦可點起點後逐格點過去。接通才會施放。':'先點板邊「起」，選一個技能；再手動接通同色「終」。',progress:'手動接線',action:modalTab==='skills'?'選擇技能':'前往技能'};}return{n:3,title:'你的第一組配置已啟動',text:'配裝與接線由你決定，戰鬥會持續進行。升級後再探索天賦與地圖。',progress:'入門完成',action:'開始自由探索'};}
function onboardingMount(){if(typeof INTRO!=='undefined'&&INTRO.active)return;const t=G.tutorial,active=!!(t?.active&&!t.done);document.body.classList.toggle('onboarding-focus',active);document.body.dataset.guideStep=active?String(t.stage):'';for(const e of document.querySelectorAll('.guide-source'))e.classList.remove('guide-source');if(active&&t.stage===2)document.querySelector('.wb .src')?.classList.add('guide-source');const old=document.getElementById('onboarding-card');if(!active){old?.remove();return;}const host=modalTab==='settings'?document.getElementById('uisettings'):document.getElementById('mbody');if(!host||host.hidden)return;const c=onboardingCopy(),key=JSON.stringify([modalTab,c]);let card=old;if(!card){card=document.createElement('section');card.id='onboarding-card';card.setAttribute('aria-label','操作入門');}if(card.parentNode!==host)host.prepend(card);if(card.dataset.key===key)return;card.dataset.key=key;card.innerHTML=`<header><span>操作入門 ${c.n}／3</span><button type="button" class="mb guide-later" onclick="onboardingPause();onboardingMount()">稍後</button></header><strong>${c.title}</strong><p>${c.text}</p><footer><span>${c.progress}</span>${c.action?`<button type="button" class="mb pri" onclick="onboardingGo()">${c.action}</button>`:''}</footer>`;}
function seasonHubHtml(){const s=seasonEnsure();return `<div class="season-hub"><header class="season-hub-head"><span>SEASON ${s.cycle+1}</span><h3>斷訊電台</h3><p>裂隙回收、三頻巡迴與午夜中樞，全部在這裡。</p></header><nav class="season-shortcuts" aria-label="本頁賽季內容"><button class="mb" onclick="seasonSection('rift')">裂隙</button><button class="mb" onclick="seasonSection('tour')">巡迴／中樞</button><button class="mb" onclick="seasonSection('forge')">專屬核心</button></nav><section id="season-rift" aria-label="賽季裂隙">${riftPanelHtml()}</section><section id="season-tour" aria-label="賽季巡迴與中樞">${seasonHtml()}</section><section id="season-forge" aria-label="本季核心鍛造"><h3>本季核心</h3><p class="uxmeta">裂隙碎片與頻段結晶各有用途，不自動裝備。</p>${activityRecipesHtml('season')}</section></div>`;}
function seasonSection(id){document.getElementById('season-'+id)?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function riftThemeUpdate(){const active=['expand','contain'].includes(G.rift?.encounter?.phase);document.body.classList.toggle('rift-active',active);if(typeof R3==='undefined'||!R3.rd||!R3.sc)return;if(active&&!R3.riftPalette){R3.riftPalette={clear:R3.rd.getClearColor(new T3.Color()).getHex(),alpha:R3.rd.getClearAlpha(),lights:[]};R3.sc.traverse(o=>{if(o.isLight){R3.riftPalette.lights.push({o,color:o.color.clone(),ground:o.groundColor?.clone()});o.color.lerp(new T3.Color('#c1a0f1'),.6);if(o.groundColor)o.groundColor.lerp(new T3.Color('#362145'),.7);}});R3.rd.setClearColor('#33224a',1);}else if(!active&&R3.riftPalette){const p=R3.riftPalette;for(const x of p.lights){x.o.color.copy(x.color);if(x.ground)x.o.groundColor.copy(x.ground);}R3.rd.setClearColor(p.clear,p.alpha);R3.riftPalette=null;}}
const ONBOARDING_FOCUS_CSS=`
.attention-dot{color:#d9413f!important;font-size:12px;vertical-align:middle}body.ui-material .attention-dot{color:#d9413f!important}
#onboarding-card{padding:10px 12px;margin:0 0 10px;border:2px solid #5e7094;background:#e2e9ee;color:#1e3152;box-shadow:2px 2px #a2b0c6}#onboarding-card header,#onboarding-card footer{display:flex;align-items:center;justify-content:space-between;gap:8px}#onboarding-card header{font-size:12px;background:transparent!important;box-shadow:none!important;margin:0;max-width:none;width:auto}#onboarding-card header>span{display:inline;color:#415879}#onboarding-card strong{display:block;font-size:18px;line-height:1.5;margin-top:3px}#onboarding-card p{font-size:13px;line-height:1.7;margin:5px 0 8px}#onboarding-card footer>span{font-size:12px}#onboarding-card .mb{font-size:12px;min-height:36px}.guide-later{padding:3px 8px!important}body.onboarding-focus #nexthint{display:none!important}body.onboarding-focus.m .stage{padding-bottom:0!important}body.onboarding-focus #mbody .sheet-group,body.onboarding-focus #mbody .sheet-defenses,body.onboarding-focus #mbody .direct-analysis-tools{display:none}body.onboarding-focus[data-guide-step="2"] #mbody .device-inventory{display:none}.guide-source{outline:3px solid #f1d17d!important;outline-offset:2px!important}.season-hub-head{display:block!important;padding:12px 0 6px;background:transparent!important;box-shadow:none!important}.season-hub-head>span{font-size:12px;color:var(--ux-muted)}.season-hub-head h3{font-size:26px;margin:4px 0}.season-hub-head p{font-size:13px;line-height:1.7}.season-shortcuts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-bottom:12px}.season-shortcuts .mb{min-width:0;font-size:12px;white-space:normal;min-height:44px}#season-rift,#season-tour,#season-forge{scroll-margin-top:8px;margin-bottom:16px}#season-tour .season-console>header h3{display:none}#season-forge>h3{font-size:20px}body.ui-material.rift-active{--ux-blue:#503973;--ux-blue-face:#69518d;--ux-ink:#2c2040;--ux-screen:#f3eafa;--ui-fx-cyan:#c0a1f0;--ui-fx-magenta:#bba4df;background-color:#241a32!important}body.ui-material.rift-active #mbody,body.ui-material.rift-active #uisettings,body.ui-material.rift-active #modal>.mbox,body.ui-material.rift-active #ovl>.mbox{background-color:#e0d9e9!important}body.ui-material.rift-active #mttl,body.ui-material.rift-active .ui-menu-group>h3{background:linear-gradient(#685187 45%,#44315f 45%)!important;border-color:#362346!important}body.rift-active #fig{position:relative}body.rift-active #fig::after{content:'';position:absolute;inset:0;pointer-events:none;z-index:5;box-shadow:inset 0 0 38px 14px #9a78d6aa,inset 0 0 90px 30px #6a4a9a66;transition:opacity .6s}
body.ui-material.rift-active #mtabs .tab.on,body.ui-material.rift-active #mbody .ui-segments button[aria-pressed=true],body.ui-material.ui-pixelfx.rift-active #mtabs button.tab.on,body.ui-material.ui-pixelfx.rift-active #mbody .ui-segments>button[aria-pressed=true]{background:#60477f!important;color:#fff!important}body.ui-material.rift-active #stats .hud-level,body.ui-material.rift-active #stats .hud-progress,body.ui-material.rift-active #stats .hud-right>div{background:#352247e8!important}body.ui-material.rift-active .stage{background-color:transparent}body.ui-material.rift-active .season-hub-head{color:#52346f}body.ui-material.rift-active #modal{border-color:#7f6597!important}
@media(max-width:359px){#onboarding-card{padding:8px}#onboarding-card strong{font-size:16px}#onboarding-card p{font-size:12px}#onboarding-card footer .mb{max-width:60%;white-space:normal}}
@media(prefers-reduced-motion:reduce){.season-hub *{scroll-behavior:auto!important}}
`;
{const style=document.createElement('style');style.textContent=ONBOARDING_FOCUS_CSS;document.head.appendChild(style);setInterval(()=>{if(typeof G==='undefined'||!document.getElementById('mbody'))return;onboardingTick();onboardingMount();riftThemeUpdate();const e=G.rift?.encounter,node=document.querySelector('[data-rift-status]');if(e&&node){const text=riftStatusLabel(e);if(node.textContent!==text)node.textContent=text;}},200);}

function onboardingIcon(){const u=deviceThumb('onboarding-device',()=>{const g=new T3.Group(),metal=m3('#b5c4d1'),ink=m3('#2d405c'),signal=m3('#90c7cb');mk(roundedG(3.5,2.8,.7),ink,0,0,0,g);mk(roundedG(2.9,2.1,.2),metal,0,.1,.5,g);for(const x of[-.7,0,.7])mk(new T3.ConeGeometry(.35,.8,3),signal,x,.2,.75,g).rotation.z=-Math.PI/2;mk(roundedG(1.1,.3,.3),signal,0,-1.6,0,g);g.rotation.set(.1,-.25,0);return g;});return u?`<img class="spr" src="${u}" alt="" width="48" height="48">`:obj3d('goals',48);}
